export function renderMufCard(o = {}) {
  const {
    farmName = 'Farm', farmSubtitle = '', logoUrl = '',
    titleEn = '', titleUr = '', monthEn = '', monthUr = '',
    rows = [], footerEn = '', footerUr = '',
    metaEn = '', metaUr = '',
