const MAX_RESET_CODE_ATTEMPTS = 5;

router.post('/reset-password', authLimiter, asyncHandler(async (req, res) => {
  const email = String(req.body?.email || '').toLowerCase().trim();
  const code = String(req.body?.code || '').trim();
  const newPassword = req.body?.newPassword;

  if (!email || !code || !newPassword) {
    return badRequest(res, 'Email, code, and new password are required.');
  }
  validateNewPassword(newPassword);

  const resetRecord = await Reset.findOne({ email });
  if (!resetRecord) return badRequest(res, 'Invalid verification code.');

  if (nowSeconds() > resetRecord.expiry) {
    await Reset.deleteOne({ _id: resetRecord._id });
    return badRequest(res, 'Verification code has expired.');
  }

  // Wrong code: count the attempt; after too many failures burn the code.
  if (resetRecord.code !== code) {
    const attempts = Number(resetRecord.attempts || 0) + 1;
    if (attempts >= MAX_RESET_CODE_ATTEMPTS) {
      await Reset.deleteOne({ _id: resetRecord._id });
      return badRequest(res, 'Too many incorrect attempts. The verification code has been invalidated — request a new one.');
    }
    await Reset.updateOne({ _id: resetRecord._id }, { $set: { attempts } });
    return badRequest(res, 'Invalid verification code.');
  }

  await User.updateOne({ email, role: { $in: MUF_FULL_ROLE_VALUES } }, { $set: { password: getPasswordHash(newPassword) } });
  await Reset.deleteOne({ _id: resetRecord._id });
  return res.json({ status: 'ok' });
}));

export default router;

import mongoose from 'mongoose';
// ─── Backup & restore (admin only) + monthly auto-backup ────────────────────
import express from 'express';
import { Setting, User, Farm, Field, MUF_FARM_MODELS, MUF_FARM_SCOPED_NAMES, Crop, Finance, Task, Inventory, Liability, Irrigation, CropPhoto, Spray, Laborer, Attendance, LaborAdvance, Supplier, SupplierPayment, DiaryMedia } from '../db.js';
import { protectUnscoped, ownerOnly } from '../middleware/auth.js';
import { mufRunUnscoped, mufMigrateFarms, MUF_FULL_ROLE_VALUES } from '../muf-farms.mjs';
import { HttpError, badRequest, notFound, asyncHandler } from '../utils/helpers.js';
import { sendEmail, mufEmail, mailConfigured } from '../utils/mailer.js';
import { MUF_ENV } from '../muf-env.mjs';

const router = express.Router();

// A backup covers every farm of this project, so only owners may take or restore
// one, and the handlers run outside any single-farm scope.
const requireAdmin = [ownerOnly, (_req, _res, next) => mufRunUnscoped(() => next())];

// Old backups have no farmId: tag whatever is untagged with the default farm.
const tagAfterRestore = () => mufMigrateFarms({ Farm, User, models: MUF_FARM_MODELS, names: MUF_FARM_SCOPED_NAMES });

// Restore farms that exist in the backup but not in the database (same ids).
async function restoreMissingFarms(payload) {
  if (!Array.isArray(payload?.farms)) return;
  for (const f of payload.farms) {
    if (f && f._id && !(await Farm.findById(String(f._id)))) {
      await Farm.create({
        _id: String(f._id), name: f.name || 'Farm', location: f.location || '',
        archived: Boolean(f.archived), createdAt: f.createdAt,
      });
    }
  }
}

const MONTHLY_AUTO_BACKUP_KEY = 'monthly_auto_backup';
const BACKUP_COLLECTIONS = [
  ['fields', Field],
  ['crops', Crop],
  ['finance', Finance],
  ['tasks', Task],
  ['inventory', Inventory],
  ['liabilities', Liability],
  ['irrigation', Irrigation],
  ['crop_photos', CropPhoto],
  ['diary_media', DiaryMedia],
  ['spray', Spray],
  ['laborers', Laborer],
  ['attendance', Attendance],
  ['labor_advances', LaborAdvance],
  ['suppliers', Supplier],
  ['supplier_payments', SupplierPayment],
];

function stringifyDocs(docs) {
  return docs.map((d) => ({ ...d, _id: String(d._id) }));
}

function currentAutoBackupName(now = new Date()) {
  return `auto-${now.toISOString().slice(0, 7)}`;
}

async function collectBackupPayload() {
  const payload = {};
  for (const [key, Model] of BACKUP_COLLECTIONS) {
    const docs = await Model.find({}).limit(100000);
    payload[key] = stringifyDocs(docs);
  }
  payload.farms = stringifyDocs(await Farm.find({}).limit(10000));
  // Archive models are regular Mongoose models, not memory-db models. In MEMORY_MODE
  // there is no Mongo connection, so querying them would buffer until timeout and
  // make even an ordinary full backup fail. The archive workflow itself is Mongo-backed.
  if (!MUF_ENV.memoryMode) {
    const ArchiveJob = mongoose.models.MufArchiveJob;
    const ArchiveRecord = mongoose.models.MufArchiveRecord;
    payload.archiveJobs = ArchiveJob ? stringifyDocs(await ArchiveJob.find({}).limit(100000)) : [];
    payload.archiveRecords = ArchiveRecord ? stringifyDocs(await ArchiveRecord.find({}).limit(100000)) : [];
  } else {
    payload.archiveJobs = [];
    payload.archiveRecords = [];
  }
  const usersList = await User.find({}).limit(100000);
  payload.users = usersList.map((u) => {
    const d = { ...u, _id: String(u._id) };
    delete d.password;
    return d;
  });
  return payload;
}

async function restoreCollection(Model, data) {
  if (data == null) return false;
  await Model.deleteMany({});
  if (!data.length) return true;
  const prepared = [];
  for (const doc of data) {
    const item = { ...doc };
    if (item._id) {
      if (/^[0-9a-fA-F]{24}$/.test(String(item._id))) {
        item._id = String(item._id);
      } else {
        delete item._id;
      }
    }
    prepared.push(item);
  }
  if (prepared.length) await Model.insertMany(prepared);
  return true;
}

async function applyBackupPayload(payload) {
  let restoredAny = false;
  await restoreMissingFarms(payload);
  for (const [key, Model] of BACKUP_COLLECTIONS) {
    if (key in payload) {
      await restoreCollection(Model, payload[key] || []);
      restoredAny = true;
    }
  }
  // Do not touch disconnected Mongoose archive models in memory demo mode.
  // Those collections are not backed by memory-db and the archive workflow is
  // unavailable there; querying them would hang until Mongoose's buffer timeout.
  if (!MUF_ENV.memoryMode) {
    for (const [key, modelName] of [['archiveJobs','MufArchiveJob'],['archiveRecords','MufArchiveRecord']]) {
      const Model = mongoose.models[modelName];
      if (Model && Array.isArray(payload[key])) {
        await Model.deleteMany({});
        if (payload[key].length) await Model.insertMany(payload[key]);
        restoredAny = true;
      }
    }
  }
  if (restoredAny) await tagAfterRestore();
  return restoredAny;
}

// Monthly auto-backup — snapshots the whole DB once per month into the
// settings collection and silently emails it to the admin (failures never
// block the backup itself).
async function maybeRunMonthlyAutoBackup(force = false) {
  const now = new Date();
  const name = currentAutoBackupName(now);
  const existing = await Setting.findOne({ key: MONTHLY_AUTO_BACKUP_KEY });
  const value = (existing && existing.value) || {};
  if (!force && value.name === name && value.payload) {
    return value;
  }
  const stored = {
    name,
    created_at: now.toISOString(),
    payload: await collectBackupPayload(),
  };
  await Setting.updateOne(
    { key: MONTHLY_AUTO_BACKUP_KEY },
    { $set: { value: stored } },
    { upsert: true },
  );
  console.log(`💾 [Auto Backup] Saved ${name}`);

  try {
    if (mailConfigured()) {
      const admin = await User.findOne({ role: { $in: MUF_FULL_ROLE_VALUES }, email: { $nin: [null, ''] } });
      const adminEmail = (admin || {}).email;
      if (adminEmail) {
        const sent = await sendEmail(
          adminEmail,
          `Usman Agri Farm — monthly backup ${name}`,
          mufEmail({
            title: `Monthly backup — ${name}`,
            bodyHtml: `<p style="margin:0;">Attached is the automatic monthly backup (<strong>${name}</strong>) of Usman Agri Farm. Keep this file safe — it can restore all farm data.</p>`,
          }),
          {
            filename: `${name}-agrifarm-backup.json`,
            content: JSON.stringify(stored.payload, null, 2),
          },
        );
        if (sent) {
          stored.emailed_to = adminEmail;
          stored.emailed_at = new Date().toISOString();
          await Setting.updateOne(
            { key: MONTHLY_AUTO_BACKUP_KEY },
            { $set: { 'value.emailed_to': stored.emailed_to, 'value.emailed_at': stored.emailed_at } },
          );
          console.log(`📧 [Auto Backup] Emailed ${name} to ${adminEmail}`);
        }
      }
    }
  } catch (mailErr) {
    console.log(`[Auto Backup] Email failed: ${mailErr.message}`);
  }
  return stored;
}

function validateBackupPayload(payload) {
  // Reject malformed backup files BEFORE any collection is wiped.
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new HttpError(400, 'Backup file must be a JSON object.');
  }
  const knownKeys = BACKUP_COLLECTIONS.map(([k]) => k);
  const present = knownKeys.filter((k) => k in payload);
  if (!present.length) {
    throw new HttpError(400, "Backup has no valid data to restore. Expected keys like 'crops', 'finance', 'tasks'...");
  }

  // Validate every collection that the restore path can mutate, including the
  // auxiliary farm/archive collections. A malformed optional section must not
  // be silently skipped or partially applied during a database-wide restore.
  const mutableKeys = [...knownKeys, 'farms', 'archiveJobs', 'archiveRecords'];
  for (const key of mutableKeys.filter((k) => k in payload)) {
    const data = payload[key];
    if (!Array.isArray(data) || data.some((doc) => !doc || typeof doc !== 'object' || Array.isArray(doc))) {
      throw new HttpError(400, `Backup section '${key}' is malformed: expected a list of records. Restore aborted — nothing was changed.`);
    }
  }
  return present;
}

// ─── Routes ──────────────────────────────────────────────────────────────────
router.get('/backup', protectUnscoped, ...requireAdmin, asyncHandler(async (_req, res) => {
  return res.json(await collectBackupPayload());
}));

router.post('/restore', protectUnscoped, ...requireAdmin, asyncHandler(async (req, res) => {
  const payload = req.body || {};
  validateBackupPayload(payload);
  // Safety net: snapshot current data into the auto-backup slot before the
  // destructive restore, so a mistaken restore can be undone via /restore/auto.
  try {
    await maybeRunMonthlyAutoBackup(true);
  } catch (snapErr) {
    console.log(`⚠️ [Restore] Pre-restore snapshot failed (continuing): ${snapErr.message}`);
  }
  if (!await applyBackupPayload(payload)) {
    return badRequest(res, 'Backup has no valid data to restore');
  }
  return res.json({ status: 'ok' });
}));

router.get('/backup/auto', protectUnscoped, ...requireAdmin, asyncHandler(async (_req, res) => {
  const existing = await Setting.findOne({ key: MONTHLY_AUTO_BACKUP_KEY });
  const value = (existing && existing.value) || {};
  if (!value.name) {
    return res.json({ exists: false, name: null, created_at: null });
  }
  return res.json({
    exists: true,
    name: value.name,
    created_at: value.created_at,
    emailed_to: value.emailed_to,
    emailed_at: value.emailed_at,
  });
}));

router.post('/restore/auto', protectUnscoped, ...requireAdmin, asyncHandler(async (req, res) => {
  const existing = await Setting.findOne({ key: MONTHLY_AUTO_BACKUP_KEY });
  const value = (existing && existing.value) || {};
  const payload = value.payload;
  if (!payload) return notFound(res, 'No automatic monthly backup is stored yet.');
  validateBackupPayload(payload);
  await applyBackupPayload(payload);
  return res.json({ status: 'ok', name: value.name });
}));

export { maybeRunMonthlyAutoBackup };
export default router;

// ─── Finance ledger routes — money-sensitive, admin-only ────────────────────
import express from 'express';
import { Finance, Crop, Field } from '../db.js';
import { protect, requireAdmin } from '../middleware/auth.js';
import { notFound, parseOid, asyncHandler, replaceFarmRecord } from '../utils/helpers.js';
import { todayStr } from '../utils/date.js';
import { cleanupOrphanPhotoAssets } from '../services/photo-assets.js';

const router = express.Router();

router.get('/finance', protect, requireAdmin, asyncHandler(async (req, res) => {
  const rawSkip = req.query.skip === undefined ? 0 : (Array.isArray(req.query.skip) ? NaN : Number(req.query.skip));
  const rawLimit = req.query.limit === undefined ? 100 : (Array.isArray(req.query.limit) ? NaN : Number(req.query.limit));
  if (!Number.isSafeInteger(rawSkip) || rawSkip < 0) return res.status(400).json({ error: 'skip must be a non-negative integer' });
  if (!Number.isSafeInteger(rawLimit) || rawLimit < 1) return res.status(400).json({ error: 'limit must be a positive integer' });
  const skip = rawSkip;
  const limit = Math.min(rawLimit, 500);
  const readFilter = (value) => typeof value === 'string' ? value.trim() : '';
  const escapeRegex = (value) => Array.from(value, (char) => {
    const code = char.charCodeAt(0);
    return [36, 46, 42, 43, 63, 94, 123, 125, 40, 41, 124, 91, 93, 92].includes(code)
      ? String.fromCharCode(92) + char : char;
  }).join('');
  const clauses = [];
  const type = readFilter(req.query.type);
  const cropId = readFilter(req.query.crop_id);
  const search = readFilter(req.query.search).slice(0, 100);
  const farmWide = ['1', 'true'].includes(readFilter(req.query.farm_wide).toLowerCase());
  if (type && type !== 'all') {
    if (type !== 'income' && type !== 'expense') return res.status(400).json({ error: 'type must be income or expense' });
    clauses.push({ type });
  }
  if (cropId && cropId !== 'all') clauses.push({ crop_id: cropId });
  else if (farmWide) {
    const cropRows = await Crop.find({}).lean();
    const existingCropIds = cropRows.map((crop) => String(crop._id));
    clauses.push({ crop_id: { $nin: existingCropIds } });
  }
  if (search) {
    const pattern = escapeRegex(search);
    clauses.push({ $or: [
      { category: { $regex: pattern, $options: 'i' } },
      { notes: { $regex: pattern, $options: 'i' } },
    ] });
  }
  const query = clauses.length === 0 ? {} : clauses.length === 1 ? clauses[0] : { $and: clauses };
  const [data, total] = await Promise.all([
    Finance.find(query).sort({ date: -1, _id: -1 }).skip(skip).limit(limit),
    Finance.countDocuments(query),
  ]);
  res.set('Access-Control-Expose-Headers', 'X-Total-Count, X-Page, X-Page-Size, X-Total-Pages');
  res.set('X-Total-Count', String(total));
  res.set('X-Page', String(Math.floor(skip / limit) + 1));
  res.set('X-Page-Size', String(limit));
  res.set('X-Total-Pages', String(Math.ceil(total / limit)));
  return res.json(data.map((d) => ({ ...d, _id: String(d._id) })));
}));


router.post('/finance/bulk', protect, requireAdmin, asyncHandler(async (req, res) => {
  const rows = req.body?.rows;
  if (!Array.isArray(rows) || rows.length < 1) return res.status(400).json({ error: 'rows must be a non-empty array' });
  if (rows.length > 200) return res.status(400).json({ error: 'A finance bulk request is limited to 200 rows' });

  const errors = [];
  const prepared = rows.map((raw, index) => {
    const rowNumber = index + 2;
    const row = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
    const category = String(row.category || '').trim();
    const type = String(row.type || 'expense').trim().toLowerCase();
    const amount = row.amount === undefined || row.amount === '' ? NaN : Number(row.amount);
    const date = String(row.date || '').trim() || todayStr();
    if (!category) errors.push({ row: rowNumber, message: 'Category is required.' });
    if (type !== 'income' && type !== 'expense') errors.push({ row: rowNumber, message: 'Type must be income or expense.' });
    if (!Number.isFinite(amount) || amount < 0) errors.push({ row: rowNumber, message: 'Amount must be a non-negative number.' });
    if (Number.isNaN(Date.parse(date))) errors.push({ row: rowNumber, message: 'Date must be valid.' });
    return {
      category, type, amount, date,
      crop_id: String(row.crop_id || '').trim() || null,
      fieldId: String(row.fieldId || '').trim() || null,
      cropCycleId: String(row.cropCycleId || '').trim() || null,
      notes: String(row.notes || '').trim(),
    };
  });
  for (let index = 0; index < prepared.length; index += 1) {
    const row = prepared[index];
    if (row.crop_id && (!/^[0-9a-fA-F]{24}$/.test(row.crop_id) || !(await Crop.findOne({ _id: row.crop_id })))) {
      errors.push({ row: index + 2, message: 'Crop must exist in the selected farm.' });
    }
    if (row.fieldId && (!/^[0-9a-fA-F]{24}$/.test(row.fieldId) || !(await Field.findOne({ _id: row.fieldId })))) {
      errors.push({ row: index + 2, message: 'Field must exist in the selected farm.' });
    }
    if (row.cropCycleId && (!/^[0-9a-fA-F]{24}$/.test(row.cropCycleId) || !(await Crop.findOne({ _id: row.cropCycleId })))) {
      errors.push({ row: index + 2, message: 'Crop cycle must exist in the selected farm.' });
    }
  }
  if (errors.length) return res.status(400).json({ error: 'Bulk finance validation failed', details: errors });
  const inserted = await Finance.insertMany(prepared);
  return res.status(201).json({ status: 'ok', inserted: inserted.length });
}));

async function validateFinanceLinks(entry) {
  const cropId = String(entry.crop_id || '').trim();
  const fieldId = String(entry.fieldId || '').trim();
  const cropCycleId = String(entry.cropCycleId || '').trim();
  if (cropId && (!/^[0-9a-fA-F]{24}$/.test(cropId) || !(await Crop.findOne({ _id: cropId })))) {
    return 'Crop must exist in the selected farm.';
  }
  if (fieldId && (!/^[0-9a-fA-F]{24}$/.test(fieldId) || !(await Field.findOne({ _id: fieldId })))) {
    return 'Field must exist in the selected farm.';
  }
  if (cropCycleId && (!/^[0-9a-fA-F]{24}$/.test(cropCycleId) || !(await Crop.findOne({ _id: cropCycleId })))) {
    return 'Crop cycle must exist in the selected farm.';
  }
  return '';
}

router.post('/finance', protect, requireAdmin, asyncHandler(async (req, res) => {
  const entry = { ...(req.body || {}) };
  const linkError = await validateFinanceLinks(entry);
  if (linkError) return res.status(400).json({ error: linkError });
  if (!entry.date) entry.date = todayStr();
  await Finance.insertMany([entry]);
  return res.status(201).json({ status: 'ok' });
}));

router.put('/finance/:financeId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.financeId, 'finance ID');
  const entry = { ...(req.body || {}) };
  const existing = await Finance.findOne({ _id: oid });
  if (existing) {
    if (!Object.prototype.hasOwnProperty.call(req.body || {}, 'fieldId') && existing.fieldId) entry.fieldId = String(existing.fieldId);
    if (!Object.prototype.hasOwnProperty.call(req.body || {}, 'cropCycleId') && existing.cropCycleId) entry.cropCycleId = String(existing.cropCycleId);
  }
  const linkError = await validateFinanceLinks(entry);
  if (linkError) return res.status(400).json({ error: linkError });
  if (!entry.date) entry.date = todayStr();
  const result = await replaceFarmRecord(Finance, oid, entry);
  if (!result.matchedCount) return notFound(res, 'Finance entry not found');
  try { await cleanupOrphanPhotoAssets(); } catch (cleanupError) { console.error('[photos] orphan cleanup deferred:', cleanupError); }
  return res.json({ status: 'ok' });
}));

router.delete('/finance/:financeId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.financeId, 'finance ID');
  const result = await Finance.deleteOne({ _id: oid });
  if (!result.deletedCount) return notFound(res, 'Finance entry not found');
  try { await cleanupOrphanPhotoAssets(); } catch (cleanupError) { console.error('[photos] orphan cleanup deferred:', cleanupError); }
  return res.json({ status: 'ok' });
}));

export default router;

