import express from 'express';
import { Laborer, Attendance, LaborAdvance, Finance, Crop } from '../db.js';
import { protect, requireAdmin } from '../middleware/auth.js';
import { badRequest, notFound, parseOid, asyncHandler, toFloat } from '../utils/helpers.js';
import { todayStr } from '../utils/date.js';

const router = express.Router();

async function validateCropLink(cropId) {
  const id = String(cropId || '').trim();
  if (!id) return '';
  if (!/^[0-9a-fA-F]{24}$/.test(id) || !(await Crop.findOne({ _id: id }))) {
    return 'Crop must exist in the selected farm.';
  }
  return '';
}

// ─── Laborers ────────────────────────────────────────────────────────────────
router.get('/laborers', protect, requireAdmin, asyncHandler(async (_req, res) => {
  const data = await Laborer.find({}).limit(100000);
  return res.json(data.map((d) => ({ ...d, _id: String(d._id) })));
}));

router.post('/laborers', protect, requireAdmin, asyncHandler(async (req, res) => {
  const body = req.body || {};
  if (!String(body.name || '').trim()) return badRequest(res, 'Worker name is required.');
  const payload = { ...body, name: String(body.name).trim(), daily_wage: toFloat(body.daily_wage) };
  const doc = (await Laborer.insertMany([payload]))[0];
  return res.status(201).json({ ...doc, _id: String(doc._id) });
}));

router.put('/laborers/:laborerId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const body = req.body || {};
  if (!String(body.name || '').trim()) return badRequest(res, 'Worker name is required.');
  const laborerId = req.params.laborerId;
  const payload = { ...body, name: String(body.name).trim(), daily_wage: toFloat(body.daily_wage) };
  const result = await Laborer.updateOne({ _id: parseOid(laborerId, 'laborer ID') }, { $set: payload });
  if (!result.matchedCount) return notFound(res, 'Field worker not found');
  return res.json({ ...payload, _id: laborerId });
}));

router.delete('/laborers/:laborerId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const laborerId = req.params.laborerId;
  const result = await Laborer.deleteOne({ _id: parseOid(laborerId, 'laborer ID') });
  if (!result.deletedCount) return notFound(res, 'Field worker not found');
  await Attendance.deleteMany({ laborer_id: laborerId });
  return res.json({ status: 'ok' });
}));

// ─── Attendance ──────────────────────────────────────────────────────────────
router.get('/attendance', protect, requireAdmin, asyncHandler(async (req, res) => {
  const month = req.query.month || null;
  const query = month ? { date: { $regex: `^${month}` } } : {};
  const data = await Attendance.find(query).limit(100000);
  return res.json(data.map((d) => ({ ...d, _id: String(d._id) })));
}));

router.post('/attendance', protect, requireAdmin, asyncHandler(async (req, res) => {
  const body = req.body || {};
  if (!body.laborer_id) return badRequest(res, 'Field worker is required.');
  const laborer = await Laborer.findOne({ _id: parseOid(body.laborer_id, 'laborer ID') });
  if (!laborer) return notFound(res, 'Field worker not found');

  const payload = { ...body };
  payload.date = payload.date || todayStr();
  payload.crop_id = payload.crop_id || null;
  const cropError = await validateCropLink(payload.crop_id);
  if (cropError) return badRequest(res, cropError);
  payload.posted = false;
  payload.day_units = payload.day_type === 'full' ? 1.0 : 0.5;

  const existing = await Attendance.findOne({ laborer_id: payload.laborer_id, date: payload.date });
  if (existing) {
    if (existing.posted) {
      return badRequest(res, 'This day is already posted to the Labor ledger.');
    }
    await Attendance.updateOne({ _id: existing._id }, { $set: payload });
    return res.status(201).json({ ...payload, _id: String(existing._id) });
  }
  const doc = (await Attendance.insertMany([payload]))[0];
  return res.status(201).json({ ...doc, _id: String(doc._id) });
}));

router.put('/attendance/:attId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.attId, 'attendance ID');
  const row = await Attendance.findOne({ _id: oid });
  if (!row) return notFound(res, 'Attendance row not found');
  if (row.posted) return badRequest(res, 'Posted attendance cannot be edited. Remove the Labor ledger entry first if needed.');
  const body = req.body || {};
  const payload = {};
  if (body.day_type !== undefined) {
    if (!['full', 'half'].includes(body.day_type)) return badRequest(res, 'day_type must be full or half');
    payload.day_type = body.day_type;
    payload.day_units = body.day_type === 'full' ? 1.0 : 0.5;
  }
  if (body.date !== undefined) {
    if (!/\d{4}-\d{2}-\d{2}/.test(String(body.date))) return badRequest(res, 'Invalid date');
    const clash = await Attendance.findOne({ laborer_id: row.laborer_id, date: String(body.date), _id: { $ne: oid } });
    if (clash) return badRequest(res, 'This worker already has attendance on that date.');
    payload.date = String(body.date);
  }
  if (body.crop_id !== undefined) {
    const cropId = body.crop_id || null;
    const cropError = await validateCropLink(cropId);
    if (cropError) return badRequest(res, cropError);
    payload.crop_id = cropId;
  }
  if (body.notes !== undefined) payload.notes = String(body.notes || '');
  await Attendance.updateOne({ _id: oid }, { $set: payload });
  return res.json({ ...row, ...payload, _id: String(row._id) });
}));

router.delete('/attendance/:attId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.attId, 'attendance ID');
  const row = await Attendance.findOne({ _id: oid });
  if (!row) return notFound(res, 'Attendance row not found');
  if (row.posted) {
    return badRequest(res, 'Posted attendance cannot be deleted. Remove the Labor ledger entry first if needed.');
  }
  await Attendance.deleteOne({ _id: oid });
  return res.json({ status: 'ok' });
}));

// ─── Labor advances ──────────────────────────────────────────────────────────
router.get('/labor-advances', protect, requireAdmin, asyncHandler(async (_req, res) => {
  const data = await LaborAdvance.find({}).limit(100000);
  return res.json(data.map((d) => ({ ...d, _id: String(d._id) })));
}));

router.post('/labor-advances', protect, requireAdmin, asyncHandler(async (req, res) => {
  const body = req.body || {};
  if (!body.laborer_id) return badRequest(res, 'Field worker is required.');
  const laborer = await Laborer.findOne({ _id: parseOid(body.laborer_id, 'laborer ID') });
  if (!laborer) return notFound(res, 'Field worker not found');
  const amount = toFloat(body.amount);
  if (!amount || amount <= 0) return badRequest(res, 'Advance amount must be greater than 0.');

  const payload = { ...body, date: body.date || todayStr(), settled: false };
  const doc = (await LaborAdvance.insertMany([payload]))[0];
  return res.status(201).json({ ...doc, _id: String(doc._id) });
}));

router.put('/labor-advances/:advId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.advId, 'advance ID');
  const row = await LaborAdvance.findOne({ _id: oid });
  if (!row) return notFound(res, 'Advance not found');
  if (row.settled) return badRequest(res, 'Settled advances cannot be edited.');
  const body = req.body || {};
  const payload = {};
  if (body.amount !== undefined) {
    const amount = toFloat(body.amount);
    if (!amount || amount <= 0) return badRequest(res, 'Advance amount must be greater than 0.');
    payload.amount = amount;
  }
  if (body.date !== undefined) {
    if (!/\d{4}-\d{2}-\d{2}/.test(String(body.date))) return badRequest(res, 'Invalid date');
    payload.date = String(body.date);
  }
  if (body.notes !== undefined) payload.notes = String(body.notes || '');
  await LaborAdvance.updateOne({ _id: oid }, { $set: payload });
  return res.json({ ...row, ...payload, _id: String(row._id) });
}));

router.delete('/labor-advances/:advId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.advId, 'advance ID');
  const row = await LaborAdvance.findOne({ _id: oid });
  if (!row) return notFound(res, 'Advance not found');
  if (row.settled) return badRequest(res, 'Settled advances cannot be deleted.');
  await LaborAdvance.deleteOne({ _id: oid });
  return res.json({ status: 'ok' });
}));

// ─── Post month wages into the finance ledger ───────────────────────────────
router.post('/labor/post-wages', protect, requireAdmin, asyncHandler(async (req, res) => {
  const month = String(req.body?.month || todayStr().slice(0, 7)).trim();
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) return badRequest(res, 'Month must be a valid YYYY-MM value.');

  const rows = await Attendance.find({ date: { $regex: `^${month}-` }, posted: { $ne: true } }).limit(100000);
  if (!rows.length) return badRequest(res, 'No unposted attendance remains for this month.');

  const laborersList = await Laborer.find({}).limit(100000);
  const laborers = {};
  for (const l of laborersList) laborers[String(l._id)] = l;

  const byLaborer = {};
  for (const row of rows) {
    const lid = row.laborer_id;
    if (!byLaborer[lid]) byLaborer[lid] = [];
    byLaborer[lid].push(row);
  }

  const lines = [];
  let total = 0;
  let totalDays = 0;
  const cropIds = rows.filter((r) => r.crop_id).map((r) => r.crop_id);
  const cropId = cropIds.length && new Set(cropIds).size === 1 ? cropIds[0] : null;

  for (const [lid, group] of Object.entries(byLaborer)) {
    const laborer = laborers[lid] || {};
    const days = Math.round(group.reduce((acc, r) => acc + toFloat(r.day_units ?? (r.day_type === 'full' ? 1.0 : 0.5)), 0) * 100) / 100;
    const wage = toFloat(laborer.daily_wage);
    const amount = Math.round(days * wage * 100) / 100;
    total += amount;
    totalDays += days;
    // Python {n:g} formatting: trim trailing zeros (24.0 -> "24")
    const g = (n) => String(Math.round(n * 100) / 100);
    lines.push(`${laborer.name || 'Worker'} ${g(days)}d × Rs. ${g(wage)}`);
  }

  if (total <= 0) {
    return badRequest(res, 'Wage total is 0. Set daily wages on field workers first.');
  }

  const fin = {
    category: 'Labor',
    amount: Math.round(total * 100) / 100,
    type: 'expense',
    date: `${month}-28`,
    crop_id: cropId,
    notes: `Monthly labor wages ${month}: ` + lines.join('; '),
    labor_workers: Number(Object.keys(byLaborer).length),
    labor_days: totalDays,
    labor_wage_rate: totalDays ? Math.round((total / totalDays) * 100) / 100 : 0,
  };
  // Advances already paid out are settled by this posting — the ledger
  // amount stays the GROSS wages (an advance was early payment of the same
  // money).
  const openAdvances = await LaborAdvance.find({ settled: { $ne: true } }).limit(100000);
  const advanceTotal = Math.round(openAdvances.reduce((acc, a) => acc + toFloat(a.amount), 0) * 100) / 100;
  if (advanceTotal > 0) {
    fin.notes += ` (advance already paid Rs. ${advanceTotal}; cash payable now Rs. ${Math.max(0, Math.round((total - advanceTotal) * 100) / 100)})`;
  }

  const finDoc = (await Finance.insertMany([fin]))[0];
  const ids = rows.map((r) => r._id);
  await Attendance.updateMany({ _id: { $in: ids } }, { $set: { posted: true, finance_id: String(finDoc._id) } });
  if (openAdvances.length) {
    await LaborAdvance.updateMany({ settled: { $ne: true } }, { $set: { settled: true } });
  }
  return res.json({ status: 'ok', amount: fin.amount, notes: fin.notes });
}));

export default router;

import express from 'express';
import mongoose from 'mongoose';
import { PhotoAsset, DiaryMedia, CropPhoto, Spray, Finance, Crop } from '../db.js';
import { protect, requireAdmin } from '../middleware/auth.js';
import { createMufStorage } from '../muf-storage.mjs';
import { MUF_ENV } from '../muf-env.mjs';
import { mufRunUnscoped } from '../muf-farms.mjs';
import { createCloudinaryClient, cloudinaryConfigured } from '../muf-cloudinary.mjs';
import { cleanupOrphanPhotoAssets, discoverOrphanPhotoAssets } from '../services/photo-assets.js';

const router = express.Router();
const TYPES = new Set(['image/jpeg', 'image/png', 'image/webp']);
function photoBytes(value) {
  if (Buffer.isBuffer(value)) return value;
  if (value instanceof Uint8Array || Array.isArray(value)) return Buffer.from(value);
  if (value && typeof value === 'object') {
    const indexes = Object.keys(value).filter((key) => /^\d+$/.test(key)).sort((a, b) => Number(a) - Number(b));
    if (indexes.length) return Buffer.from(indexes.map((key) => Number(value[key])));
    if (value.type === 'Buffer' && Array.isArray(value.data)) return Buffer.from(value.data);
  }
  return Buffer.alloc(0);
}
function parseDataUrl(value) {
  const match = typeof value === 'string' && value.match(/^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=]+)$/);
  if (!match || !TYPES.has(match[1])) return null;
  const bytes = Buffer.from(match[2], 'base64');
  return bytes.length ? { bytes, contentType: match[1] } : null;
}
let cloudinaryFallbackLogged = false;
function configuredCloudinary() {
  const config = { cloudName: MUF_ENV.cloudinaryCloudName, apiKey: MUF_ENV.cloudinaryApiKey, apiSecret: MUF_ENV.cloudinaryApiSecret };
  if (!cloudinaryConfigured(config)) {
    if (!cloudinaryFallbackLogged) {
      console.info('[photo-storage] Cloudinary credentials are incomplete; using MongoDB photo storage.');
      cloudinaryFallbackLogged = true;
    }
    return null;
  }
  return createCloudinaryClient(config);
}
function storage() {
  const cloudinary = configuredCloudinary();
  return createMufStorage({ store: {
    async save({ bytes, contentType, metadata = {} }) {
      if (cloudinary) {
        const remote = await cloudinary.upload({ bytes, contentType });
        const doc = await PhotoAsset.create({
          provider: 'cloudinary', cloudinaryPublicId: remote.publicId, secureUrl: remote.secureUrl,
          contentType, size: bytes.length, createdBy: String(metadata.createdBy || ''), createdAt: new Date(),
        });
        return { id: String(doc._id) };
      }
      const doc = await PhotoAsset.create({ provider: 'mongodb', contentType, data: bytes, size: bytes.length, createdBy: String(metadata.createdBy || ''), createdAt: new Date() });
      return { id: String(doc._id) };
    },
    async readLink(id) {
      const doc = await PhotoAsset.findById(id).select('_id').lean();
      return doc ? `/api/photos/${doc._id}` : null;
    },
    async delete(id) {
      const doc = await PhotoAsset.findById(id);
      if (!doc) return false;
      if (doc.provider === 'cloudinary' && doc.cloudinaryPublicId) {
        if (!cloudinary) throw new Error('Cloudinary credentials are required to delete this photo');
        await cloudinary.destroy(doc.cloudinaryPublicId);
      }
      return (await PhotoAsset.deleteOne({ _id: id })).deletedCount > 0;
    },
    async list() { return (await PhotoAsset.find({}).select('_id').lean()).map((d) => ({ id: String(d._id) })); },
  }});
}
function referencesId(value, id, seen = new Set()) {
  if (typeof value === 'string') return value.includes('/api/photos/' + id);
  if (!value || typeof value !== 'object' || seen.has(value)) return false;
  seen.add(value);
  return (Array.isArray(value) ? value : Object.values(value)).some((v) => referencesId(v, id, seen));
}
async function isReferenced(id) {
  // An asset must not be deleted just because its reference lives in another
  // farm. Read reference records across farms, but expose no records to caller.
  return mufRunUnscoped(async () => {
    for (const Model of [DiaryMedia, CropPhoto, Spray, Finance, Crop]) {
      const rows = await Model.find({}).lean();
      if (rows.some((row) => referencesId(row, id))) return true;
    }
    return false;
  });
}
router.post('/photos', protect, async (req, res) => {
  try {
    const parsed = parseDataUrl(req.body?.data);
    if (!parsed) return res.status(400).json({ error: 'Photo must be a valid JPEG, PNG or WebP data URL' });
    const saved = await storage().save({ ...parsed, metadata: { createdBy: req.user?.username || '' } });
    return res.status(201).json({ id: saved.id, path: `/api/photos/${saved.id}` });
  } catch (err) {
    const status = err instanceof RangeError ? 413 : err instanceof TypeError ? 400 : 500;
    return res.status(status).json({ error: err.message || 'Photo upload failed' });
  }
});
router.get('/photos/orphans', protect, requireAdmin, async (req, res) => {
  try {
    return res.json(await discoverOrphanPhotoAssets());
  } catch (err) {
    return res.status(500).json({ error: err.message || 'Photo orphan discovery failed' });
  }
});
router.post('/photos/cleanup-orphans', protect, requireAdmin, async (req, res) => {
  try {
    return res.json(await cleanupOrphanPhotoAssets());
  } catch (err) {
    return res.status(500).json({ error: err.message || 'Photo orphan cleanup failed' });
  }
});
router.get('/photos/:id', protect, async (req, res) => {
  try {
    if (!mongoose.isValidObjectId(req.params.id)) return res.status(404).json({ error: 'Photo not found' });
    const photo = await PhotoAsset.findById(req.params.id);
    if (!photo) return res.status(404).json({ error: 'Photo not found' });
    if (photo.provider === 'cloudinary') {
      let remoteUrl;
      try { remoteUrl = new URL(photo.secureUrl); } catch { return res.status(502).json({ error: 'Stored Cloudinary URL is invalid' }); }
      if (remoteUrl.protocol !== 'https:' || remoteUrl.hostname !== 'res.cloudinary.com') {
        return res.status(502).json({ error: 'Stored Cloudinary URL is not trusted' });
      }
      const remote = await fetch(remoteUrl);
      if (!remote.ok) return res.status(502).json({ error: 'Cloudinary photo retrieval failed' });
      const bytes = Buffer.from(await remote.arrayBuffer());
      return res.set('Content-Type', photo.contentType || remote.headers.get('content-type') || 'application/octet-stream')
        .set('Cache-Control', 'private, max-age=3600')
        .send(bytes);
    }
    return res
      .set('Content-Type', photo.contentType || 'application/octet-stream')
      .set('Cache-Control', 'private, max-age=3600')
      .send(photoBytes(photo.data));
  } catch (err) {
    return res.status(500).json({ error: err.message || 'Photo retrieval failed' });
  }
});
router.delete('/photos/:id', protect, async (req, res) => {
  try {
    if (!mongoose.isValidObjectId(req.params.id)) return res.status(404).json({ error: 'Photo not found' });
    if (await isReferenced(req.params.id)) return res.status(409).json({ error: 'Photo is still referenced by a farm record' });
    // The storage adapter removes the remote Cloudinary object before deleting
    // its metadata, while preserving the MongoDB fallback and old local assets.
    const deleted = await storage().delete(req.params.id);
    if (!deleted) return res.status(404).json({ error: 'Photo not found' });
    return res.json({ ok: true });
  } catch (err) {
    return res.status(500).json({ error: err.message || 'Photo deletion failed' });
  }
});
export default router;

// ─── Task routes (mirrors the previous FastAPI backend) ─────────────────────
// Completing a task auto-logs a Labor expense, deducts inventory, and marks
// the deployed field crew's attendance for today.
import express from 'express';
import { Task, Finance, Inventory, Laborer, Attendance, Crop } from '../db.js';
import { mufIsFullRole } from '../muf-farms.mjs';
import { protect, requireAdmin } from '../middleware/auth.js';
import { notFound, forbidden, parseOid, asyncHandler, replaceFarmRecord } from '../utils/helpers.js';
import { todayStr } from '../utils/date.js';

const router = express.Router();

router.get('/tasks', protect, asyncHandler(async (req, res) => {
  const rawSkip = req.query.skip === undefined ? 0 : (Array.isArray(req.query.skip) ? NaN : Number(req.query.skip));
  const rawLimit = req.query.limit === undefined ? 100 : (Array.isArray(req.query.limit) ? NaN : Number(req.query.limit));
  if (!Number.isSafeInteger(rawSkip) || rawSkip < 0) return res.status(400).json({ error: 'skip must be a non-negative integer' });
  if (!Number.isSafeInteger(rawLimit) || rawLimit < 1) return res.status(400).json({ error: 'limit must be a positive integer' });
  const skip = rawSkip;
  const limit = Math.min(rawLimit, 500);
  const readFilter = (value) => typeof value === 'string' ? value.trim() : '';
  const escapeRegex = (value) => Array.from(value, (char) => {
    const code = char.charCodeAt(0);
    return [36, 46, 42, 43, 63, 94, 123, 125, 40, 41, 124, 91, 93, 92].includes(code)
      ? String.fromCharCode(92) + char : char;
  }).join('');
  const clauses = [];
  const status = readFilter(req.query.status);
  const cropId = readFilter(req.query.crop_id);
  const searchTerms = readFilter(req.query.crop_search).slice(0, 240).split('|').map((part) => part.trim()).filter(Boolean).slice(0, 4);
  if (status && status !== 'all') clauses.push({ status });
  if (cropId && cropId !== 'all' && !/^[0-9a-fA-F]{24}$/.test(cropId)) {
    return res.status(400).json({ error: 'crop_id must be a valid crop ID' });
  }
  // Legacy tasks may reference crops by title/notes rather than crop_id.
  // Treat explicit links and text matches as alternatives, while status remains
  // an independent AND condition.
  const cropMatches = [];
  if (cropId && cropId !== 'all') cropMatches.push({ crop_id: cropId });
  for (const term of searchTerms) {
    const pattern = escapeRegex(term.slice(0, 80));
    cropMatches.push({ title: { $regex: pattern, $options: 'i' } }, { notes: { $regex: pattern, $options: 'i' } });
  }
  if (cropMatches.length) clauses.push({ $or: cropMatches });
  const query = clauses.length === 0 ? {} : clauses.length === 1 ? clauses[0] : { $and: clauses };
  const [data, total] = await Promise.all([
    Task.find(query).sort({ createdAt: -1, _id: -1 }).skip(skip).limit(limit),
    Task.countDocuments(query),
  ]);
  res.set('Access-Control-Expose-Headers', 'X-Total-Count, X-Page, X-Page-Size, X-Total-Pages');
  res.set('X-Total-Count', String(total));
  res.set('X-Page', String(Math.floor(skip / limit) + 1));
  res.set('X-Page-Size', String(limit));
  res.set('X-Total-Pages', String(Math.ceil(total / limit)));
  return res.json(data.map((d) => ({ ...d, _id: String(d._id) })));
}));


router.post('/tasks/bulk', protect, requireAdmin, asyncHandler(async (req, res) => {
  const rows = req.body?.rows;
  if (!Array.isArray(rows) || rows.length < 1) return res.status(400).json({ error: 'rows must be a non-empty array' });
  if (rows.length > 200) return res.status(400).json({ error: 'A task bulk request is limited to 200 rows' });

  const errors = [];
  const allowedPriorities = new Set(['Low', 'Medium', 'High']);
  const prepared = rows.map((raw, index) => {
    const rowNumber = index + 2;
    const row = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
    const title = String(row.title || '').trim();
    const priority = String(row.priority || 'Medium').trim();
    const dueDate = String(row.due_date || '').trim();
    const laborCost = row.labor_cost === undefined || row.labor_cost === '' ? 0 : Number(row.labor_cost);
    if (!title) errors.push({ row: rowNumber, message: 'Task title is required.' });
    if (!allowedPriorities.has(priority)) errors.push({ row: rowNumber, message: 'Priority must be Low, Medium, or High.' });
    if (dueDate && Number.isNaN(Date.parse(dueDate))) errors.push({ row: rowNumber, message: 'Due date must be valid.' });
    if (!Number.isFinite(laborCost) || laborCost < 0) errors.push({ row: rowNumber, message: 'Labor cost must be a non-negative number.' });
    return {
      title,
      due_date: dueDate,
      assigned_to: String(row.assigned_to || '').trim(),
      priority,
      notes: String(row.notes || ''),
      labor_cost: laborCost,
      crop_id: String(row.crop_id || '').trim() || null,
      inventory_item_id: String(row.inventory_item_id || '').trim() || null,
      inventory_qty_consumed: row.inventory_qty_consumed === undefined || row.inventory_qty_consumed === '' ? 0 : Number(row.inventory_qty_consumed),
      laborer_ids: Array.isArray(row.laborer_ids) ? row.laborer_ids : [],
      status: 'Pending',
    };
  });
  for (let index = 0; index < prepared.length; index += 1) {
    const row = prepared[index];
    if (!Number.isFinite(row.inventory_qty_consumed) || row.inventory_qty_consumed < 0) {
      errors.push({ row: index + 2, message: 'Inventory quantity must be a non-negative number.' });
    }
    if (row.crop_id) {
      if (!/^[0-9a-fA-F]{24}$/.test(row.crop_id) || !(await Crop.findOne({ _id: row.crop_id }))) {
        errors.push({ row: index + 2, message: 'Crop must exist in the selected farm.' });
      }
    }
    if (row.inventory_item_id) {
      if (!/^[0-9a-fA-F]{24}$/.test(row.inventory_item_id) || !(await Inventory.findOne({ _id: row.inventory_item_id }))) {
        errors.push({ row: index + 2, message: 'Inventory item must exist in the selected farm.' });
      }
    }
  }
  if (errors.length) return res.status(400).json({ error: 'Bulk task validation failed', details: errors });

  for (const task of prepared) {
    [task.laborer_ids, task.laborer_names] = await cleanLaborerIds(task.laborer_ids);
  }
  const inserted = await Task.insertMany(prepared);
  return res.status(201).json({ status: 'ok', inserted: inserted.length });
}));

async function validateTaskLinks(task) {
  const cropId = String(task.crop_id || '').trim();
  const inventoryId = String(task.inventory_item_id || '').trim();
  const quantity = task.inventory_qty_consumed === undefined || task.inventory_qty_consumed === '' ? 0 : Number(task.inventory_qty_consumed);
  if (!Number.isFinite(quantity) || quantity < 0) return 'Inventory quantity must be a non-negative number.';
  if (cropId && (!/^[0-9a-fA-F]{24}$/.test(cropId) || !(await Crop.findOne({ _id: cropId })))) {
    return 'Crop must exist in the selected farm.';
  }
  if (inventoryId && (!/^[0-9a-fA-F]{24}$/.test(inventoryId) || !(await Inventory.findOne({ _id: inventoryId })))) {
    return 'Inventory item must exist in the selected farm.';
  }
  return '';
}

// Keep only valid, existing laborer ids (deduped, max 30). Names are
// resolved server-side so task cards can display the crew without needing
// wage-bearing /laborers access.
async function cleanLaborerIds(rawIds) {
  const cleaned = [];
  const names = [];
  for (const lid of (rawIds || []).slice(0, 30)) {
    if (typeof lid !== 'string' || cleaned.includes(lid)) continue;
    if (!/^[0-9a-fA-F]{24}$/.test(lid)) continue;
    try {
      const laborer = await Laborer.findOne({ _id: lid });
      if (laborer) {
        cleaned.push(lid);
        names.push(laborer.name || 'Worker');
      }
    } catch { /* skip */ }
  }
  return [cleaned, names];
}

router.post('/tasks', protect, requireAdmin, asyncHandler(async (req, res) => {
  const task = { ...(req.body || {}), status: 'Pending' };
  const linkError = await validateTaskLinks(task);
  if (linkError) return res.status(400).json({ error: linkError });
  [task.laborer_ids, task.laborer_names] = await cleanLaborerIds(task.laborer_ids);
  await Task.insertMany([task]);
  return res.status(201).json({ status: 'ok' });
}));

router.put('/tasks/:taskId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.taskId, 'task ID');
  const task = { ...(req.body || {}) };
  const linkError = await validateTaskLinks(task);
  if (linkError) return res.status(400).json({ error: linkError });
  [task.laborer_ids, task.laborer_names] = await cleanLaborerIds(task.laborer_ids);
  const result = await replaceFarmRecord(Task, oid, task);
  if (!result.matchedCount) return notFound(res, 'Task not found');
  return res.json({ status: 'ok' });
}));

router.patch('/tasks/:taskId', protect, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.taskId, 'task ID');
  const task = await Task.findOne({ _id: oid });
  if (!task) return notFound(res, 'Task not found');

  // Authorization: admins can complete any task; a worker may only complete
  // tasks assigned to them.
  if (!mufIsFullRole(req.user.role)) {
    const assignedTo = String(task.assigned_to || '').toLowerCase().trim();
    if (assignedTo !== String(req.user.username || '').toLowerCase().trim()) {
      return forbidden(res, 'You can only complete tasks that are assigned to you.');
    }
  }

  // Idempotency guard: completing an already-completed task must not
  // double-log labor wages or double-deduct inventory.
  if (task.status === 'Completed') {
    return res.json({ status: 'ok', already_completed: true });
  }

  await Task.updateOne({ _id: oid }, { $set: { status: 'Completed' } });

  // 1. Auto-log labor wages if greater than 0
  const laborCost = Number(task.labor_cost || 0);
  if (laborCost > 0) {
    try {
      await Finance.insertMany([{
        category: `Labor Wages - ${task.title}`,
        amount: laborCost,
        type: 'expense',
        date: todayStr(),
        crop_id: null,
        notes: `Wages paid to ${task.assigned_to || 'Workers'} for completing task: ${task.title}`,
      }]);
    } catch (finErr) {
      console.log('Failed to auto-log labor wage:', finErr.message);
    }
  }

  // 2. Auto-deduct inventory if specified (only when enough stock is available)
  const invItemId = task.inventory_item_id;
  const qtyConsumed = Number(task.inventory_qty_consumed || 0);
  if (invItemId && qtyConsumed > 0) {
    try {
      const invItem = await Inventory.findOne({ _id: String(invItemId) });
      if (invItem && (Number(invItem.current_stock) || 0) >= qtyConsumed) {
        await Inventory.updateOne({ _id: String(invItemId) }, { $inc: { current_stock: -qtyConsumed } });
      } else {
        console.log(`⚠️ Skipped inventory deduction: insufficient stock or item not found for ${invItemId}`);
      }
    } catch (invErr) {
      console.log('Failed to auto-deduct inventory stock:', invErr.message);
    }
  }

  // 3. Auto-mark attendance for the deployed field crew (full day, today).
  // Skips laborers already marked for the date so manual entries are never
  // overwritten; posted (locked) days are also left untouched.
  const crewIds = task.laborer_ids || [];
  let crewMarked = 0;
  if (crewIds.length) {
    const attDate = todayStr();
    for (const lid of crewIds) {
      try {
        const laborer = await Laborer.findOne({ _id: lid });
        if (!laborer) continue;
        const existing = await Attendance.findOne({ laborer_id: lid, date: attDate });
        if (existing) continue; // already marked today (manually or by another task)
        await Attendance.insertMany([{
          laborer_id: lid,
          date: attDate,
          day_type: 'full',
          day_units: 1.0,
          crop_id: task.crop_id || null,
          field: '',
          notes: `Auto: task '${task.title}' completed`,
          posted: false,
        }]);
        crewMarked += 1;
      } catch (attErr) {
        console.log('Failed to auto-mark crew attendance:', attErr.message);
      }
    }
  }

  return res.json({ status: 'ok', crew_attendance_marked: crewMarked });
}));

router.delete('/tasks/:taskId', protect, requireAdmin, asyncHandler(async (req, res) => {
  const oid = parseOid(req.params.taskId, 'task ID');
  const result = await Task.deleteOne({ _id: oid });
  if (!result.deletedCount) return notFound(res, 'Task not found');
  return res.json({ status: 'ok' });
}));

export default router;

// ─── Telegram bot for Usman Agri Farm ────────────────────────────────────────
// Workers send simple messages ("kharcha 500 spray", "hazri", "hisab") and
// the bot writes into the SAME collections the app writes. Command parsing +
// reply texts live in the shared muf-telegram twin (../muf-telegram.mjs).
// Webhook-based (autoscale-safe).
//
// Secrets: TELEGRAM_BOT_TOKEN (from @BotFather), TELEGRAM_WEBHOOK_SECRET
// (any long random string). Both unset → telegram stays silently off.
import express from 'express';
import crypto from 'node:crypto';
import rateLimit from 'express-rate-limit';
import { TelegramMeta, User, Laborer, Finance, Attendance, Crop, Farm } from '../db.js';
import { protect, requireAdmin } from '../middleware/auth.js';
import { parseOid, asyncHandler, toFloat } from '../utils/helpers.js';
import { todayStr } from '../utils/date.js';
import { MUF_ENV, mufTestRateLimitMax } from '../muf-env.mjs';
import { mufGetDefaultFarmId, mufGetFarmContext, mufRunWithFarmContext, mufIsFullRole, mufIsOwner } from '../muf-farms.mjs';
import { mufTelegramFarmId, mufRunTelegramFarm } from '../muf-telegram-farms.mjs';

let mufTelegram = null; // ESM twin, loaded once on first use
async function muf() {
  if (!mufTelegram) mufTelegram = await import('../muf-telegram.mjs');
  return mufTelegram;
}

const router = express.Router();

const TOKEN = () => MUF_ENV.telegramBotToken || '';
const WH_SECRET = () => MUF_ENV.telegramWebhookSecret || '';

function timingSafeSecretEqual(provided, expected) {
  const a = Buffer.from(String(provided || ''));
  const b = Buffer.from(String(expected || ''));
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

async function tgRead(key) {
  const doc = await TelegramMeta.findOne({ key });
  return (doc && doc.value) || {};
}

async function tgWrite(key, value) {
  await TelegramMeta.updateOne({ key }, { $set: { key, value } }, { upsert: true });
}

const AGRI_TG_HELP = [
  '🌾 عثمان ایگری فارم بوٹ — ایسے لکھیں:',
  '',
  'kharcha 500 spray  ← 500 روپے سپرے کا خرچہ',
  'hazri  ← اپنی آج کی حاضری',
  'hisab  ← آج کا خلاصہ',
].join('\n');

router.get('/status', protect, requireAdmin, asyncHandler(async (_req, res) => {
  const token = TOKEN();
  const links = await tgRead('links');
  const m = await muf();
  const bot = token ? await m.tgGetBotUsername(token) : null;
  return res.json({
    configured: Boolean(token && WH_SECRET()),
    botUsername: bot,
    links: Object.entries(links).filter(([, v]) => mufTelegramFarmId(v) === String(mufGetFarmContext()?.farmId || '')).map(([chatId, v]) => ({ chatId, ...v })),
  });
}));

router.post('/link-code', protect, requireAdmin, asyncHandler(async (req, res) => {
  const body = req.body || {};
  const userId = String(body.userId || '');
  const laborerId = String(body.laborerId || '');
  const farmId = mufGetFarmContext()?.farmId;
  if (!farmId) return res.status(400).json({ detail: 'Select one farm before creating a Telegram link code' });
  let username = '';
  let laborerName = '';
  if (userId) {
    const u = await User.findOne({ _id: parseOid(userId, 'user ID') });
    if (!u) return res.status(404).json({ detail: 'User not found' });
    const assignedFarmIds = (u.farmIds || []).map(String);
    if (!mufIsOwner(u.role) && !assignedFarmIds.includes(String(farmId))) {
      return res.status(404).json({ detail: 'User not found in the selected farm' });
    }
    username = u.username || '';
  }
  if (laborerId) {
    const lw = await Laborer.findOne({ _id: parseOid(laborerId, 'worker ID') });
    if (!lw) return res.status(404).json({ detail: 'Worker not found' });
    laborerName = lw.name || '';
  }
  if (!userId && !laborerId) {
    return res.status(400).json({ detail: 'Pick an app user or a wage worker to link' });
  }
  const codes = await tgRead('codes');
  const nowMs = Date.now();
  const fresh = {};
  for (const [c, v] of Object.entries(codes)) {
    if ((v.expires || 0) >= nowMs) fresh[c] = v;
  }
  const m = await muf();
  const code = m.tgNewLinkCode();
  fresh[code] = {
