/* ── Telegram HTTP helpers (no extra packages — global fetch) ── */

export async function tgSendMessage(token, chatId, text) {
  if (!token || !chatId) return false;
  try {
    const res = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text }),
    });
    return res.ok;
  } catch {
    return false; // never let a Telegram hiccup break the webhook
  }
}

/** Register the webhook with Telegram (called once at boot, non-fatal). */
export async function tgSetWebhook(token, url) {
  if (!token || !url) return false;
  try {
    const res = await fetch(`https://api.telegram.org/bot${token}/setWebhook?url=${encodeURIComponent(url)}`);
    const body = await res.json().catch(() => ({}));
    return !!body.ok;
  } catch {
    return false;
  }
}

/** Bot's @username (shown in the admin UI instructions). */
export async function tgGetBotUsername(token) {
  if (!token) return null;
  try {
    const res = await fetch(`https://api.telegram.org/bot${token}/getMe`);
    const body = await res.json().catch(() => ({}));
    return body.ok ? body.result.username : null;
  } catch {
    return null;
  }
}

/** 6-digit link code. */
export function tgNewLinkCode() {
  return String(Math.floor(100000 + Math.random() * 900000));
}

/* ── Production-drop alarm + evening auto-summary helpers ─────────
 * Shared math for the "aaj ki paidawar kam hai" alarm: compare today's
 * total (milk liters / eggs) with the previous days' average. Callers
 * decide when "today" is complete (dairy: evening milk entered; flock:
 * today's egg count entered) and pass the threshold % from settings. */

/**
 * mufDropCheck(todayTotal, prevTotals, thresholdPct)
 * prevTotals = totals of the last ~7 days; zero/empty days are ignored.
 * Needs at least 3 non-zero previous days, else { ready:false }.
 * Returns { ready, drop, avg, pct } — pct = % below the average (>= 0).
 */
export function mufDropCheck(todayTotal, prevTotals, thresholdPct = 20) {
  const days = (Array.isArray(prevTotals) ? prevTotals : [])
    .map(Number).filter((v) => Number.isFinite(v) && v > 0);
  if (days.length < 3) return { ready: false, drop: false, avg: 0, pct: 0 };
  const avg = days.reduce((a, b) => a + b, 0) / days.length;
  const today = Number(todayTotal) || 0;
  const pct = Math.max(0, Math.round(((avg - today) / avg) * 100));
  const threshold = Number(thresholdPct) > 0 ? Number(thresholdPct) : 20;
  return { ready: true, drop: today < avg * (1 - threshold / 100), avg: Math.round(avg * 10) / 10, pct };
}

/** Urdu alarm block appended to the evening summary when production drops. */
export function tgDropAlert(pct, todayLine, avgLine) {
  return [
    `⚠️ خبردار! آج کی پیداوار 7 دن کی اوسط سے ${pct}% کم ہے۔`,
    todayLine,
    avgLine,
    'ذرا دیکھ لیں — صحت، خوراک یا موسم میں کوئی مسئلہ تو نہیں۔',
  ].join('\n');
}

import express from 'express';
const router = express.Router();
import mongoose from 'mongoose';
import { Cow, Milk, Expense, Rate, Health, Buyer, BuyerPayment, RateHistory, DailyLog, Sale, Meta, Laborer, LaborAttendance, LaborAdvance, Supplier, SupplierPayment, BreedingEvent, User, Farm, ArchiveJob, ArchiveRecord, MUF_FARM_MODELS, MUF_FARM_SCOPED_NAMES } from '../db.js';
import { protectUnscoped, ownerOnly } from '../middleware/auth.js';
import { mufRunUnscoped, mufMigrateFarms, MUF_FULL_ROLE_VALUES } from '../muf-farms.mjs';

// A backup covers every farm of this project, so only owners may take or restore
// one, and the handlers run outside any single-farm scope.
const adminOnly = [ownerOnly, (_req, _res, next) => mufRunUnscoped(() => next())];

// Old backups have no farmId: tag whatever is untagged with the default farm.
const tagAfterRestore = () => mufMigrateFarms({ Farm, User, models: MUF_FARM_MODELS, names: MUF_FARM_SCOPED_NAMES });

// Restore farms that exist in the backup but not in the database (same ids).
async function restoreMissingFarms(payload) {
  if (!Array.isArray(payload?.farms)) return;
  for (const f of payload.farms) {
    if (f && f._id && !(await Farm.findById(String(f._id)))) {
      await Farm.create({ _id: f._id, name: f.name || 'Farm', location: f.location || '', archived: Boolean(f.archived) });
    }
  }
}
import { sendMail, mailConfigured, mufEmail } from '../utils/mailer.js';
import { MUF_ENV } from '../muf-env.mjs';

// GET /api/backup — download full database as JSON
router.get('/', protectUnscoped, ...adminOnly, async (req, res) => {
  try {
    const [cows, milk, expenses, rates, health, buyers, buyerPayments, rateHistory, dailyLogs, sales, laborers, laborAttendance, laborAdvances, suppliers, supplierPayments, breedingEvents] = await Promise.all([
      Cow.find().lean(),
      Milk.find().lean(),
      Expense.find().lean(),
      Rate.find().lean(),
      Health.find().lean(),
      Buyer.find().lean(),
      BuyerPayment.find().lean(),
      RateHistory.find().lean(),
      DailyLog.find().lean(),
      Sale.find().lean(),
      Laborer.find().lean(),
      LaborAttendance.find().lean(),
      LaborAdvance.find().lean(), Supplier.find().lean(), SupplierPayment.find().lean(), BreedingEvent.find().lean(),
    ]);
    const farms = await Farm.find().lean();
    const backup = {
      exportDate: new Date().toISOString(),
      farmName: 'Usman Dairy Farm',
      version: 4,
      farms,
      cows, milk, expenses, rates, health, buyers, buyerPayments, rateHistory, dailyLogs, sales, laborers, laborAttendance, laborAdvances, suppliers, supplierPayments, breedingEvents,
      archiveJobs: await ArchiveJob.find().lean(), archiveRecords: await ArchiveRecord.find().lean()
    };
    res.setHeader('Content-Disposition', `attachment; filename=usman-dairy-backup-${new Date().toISOString().slice(0,10)}.json`);
    res.setHeader('Content-Type', 'application/json');
    res.json(backup);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

const COLLECTIONS = {
  cows: Cow,
  milk: Milk,
  expenses: Expense,
  rates: Rate,
  health: Health,
  buyers: Buyer,
  buyerPayments: BuyerPayment,
  rateHistory: RateHistory,
  dailyLogs: DailyLog,
  sales: Sale,
  laborers: Laborer,
  laborAttendance: LaborAttendance,
  laborAdvances: LaborAdvance,
  suppliers: Supplier,
  supplierPayments: SupplierPayment,
  breedingEvents: BreedingEvent,
  archiveJobs: ArchiveJob,
  archiveRecords: ArchiveRecord,
};

function validateBackupPayload(payload) {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new Error('Invalid backup payload');
  }
  for (const [key, Model] of Object.entries(COLLECTIONS)) {
    void Model;
    const data = payload[key];
    if (data !== undefined && (!Array.isArray(data) || data.some((doc) => !doc || typeof doc !== 'object' || Array.isArray(doc)))) {
      throw new Error(`"${key}" must be an array of records if present`);
    }
  }
  if (payload.farms !== undefined && (!Array.isArray(payload.farms) || payload.farms.some((farm) => !farm || typeof farm !== 'object' || Array.isArray(farm)))) {
    throw new Error('"farms" must be an array of records if present');
  }
}

async function restoreCollections(payload, session) {
  const opts = session ? { session } : {};
  for (const [key, Model] of Object.entries(COLLECTIONS)) {
    const data = payload[key];
    // Only touch collections that are present AND are arrays with content intent.
    // Empty array still means "clear this collection" when the key is present.
    if (data === undefined || !Array.isArray(data)) continue;
    await Model.deleteMany({}, opts);
    if (data.length > 0) {
      // insertMany in chunks to avoid huge single ops
      const chunkSize = 500;
      for (let i = 0; i < data.length; i += chunkSize) {
        const chunk = data.slice(i, i + chunkSize);
        await Model.insertMany(chunk, { ...opts, ordered: false });
      }
    }
  }
}

// POST /api/backup/restore — restore from JSON backup
// Uses a transaction when the deployment supports it (replica set / Atlas).
// Falls back to sequential restore on standalone MongoDB.
router.post('/restore', protectUnscoped, ...adminOnly, async (req, res) => {
  const payload = req.body;
  try {
    validateBackupPayload(payload);
  } catch (validationError) {
    return res.status(400).json({ error: validationError.message });
  }

  const hasData = Object.keys(COLLECTIONS).some(key => Array.isArray(payload[key]) && payload[key].length > 0);
  if (!hasData) {
    return res.status(400).json({ error: 'Backup contains no data to restore' });
  }

  // Prefer atomic transaction; fall back for standalone Mongo / memory mode.
  // IMPORTANT: startSession() must live INSIDE the try — in memory mode there
  // is no Mongo connection, it throws after a buffering timeout, and an
  // unhandled rejection here used to CRASH the whole server.
  let session = null;
  try {
    let usedTransaction = false;

    if (!MUF_ENV.memoryMode && mongoose.connection.readyState === 1) {
      try { session = await mongoose.startSession(); } catch { session = null; }
    }

    await restoreMissingFarms(payload);
    if (session) {
      try {
        await session.withTransaction(async () => {
          await restoreCollections(payload, session);
        });
        usedTransaction = true;
      } catch (txErr) {
        const msg = String(txErr?.message || txErr || '');
        const noTxn =
          msg.includes('Transaction numbers are only allowed') ||
          msg.includes('replica set') ||
          msg.includes('not supported') ||
          txErr?.code === 20 ||
          txErr?.codeName === 'IllegalOperation';

        if (!noTxn) throw txErr;

        // Standalone fallback — not atomic, but functional
        console.warn('Backup restore: transactions unavailable, using sequential restore.');
        await restoreCollections(payload, null);
      }
    } else {
      // Memory mode / not connected: plain sequential restore.
      await restoreCollections(payload, null);
    }

    await tagAfterRestore();
    res.json({
      success: true,
      message: usedTransaction
        ? 'Data restored successfully (atomic)'
        : 'Data restored successfully (sequential)',
    });
  } catch (e) {
    res.status(500).json({ error: `Restore failed: ${e.message}` });
  } finally {
    if (session) session.endSession();
  }
});


// ─── Monthly Auto-Backup ──────────────────────────
// Once per calendar month a full snapshot of the database is stored inside
// the DB itself (Meta collection) under the name auto-YYYY-MM. It runs at
// server boot; if this month's snapshot already exists nothing happens.
const MONTHLY_AUTO_BACKUP_KEY = 'monthly_auto_backup';

async function collectBackupPayload() {
  const [cows, milk, expenses, rates, health, buyers, buyerPayments, rateHistory, dailyLogs, sales, laborers, laborAttendance, laborAdvances, suppliers, supplierPayments, breedingEvents] = await Promise.all([
    Cow.find().lean(), Milk.find().lean(), Expense.find().lean(), Rate.find().lean(),
    Health.find().lean(), Buyer.find().lean(), BuyerPayment.find().lean(), RateHistory.find().lean(), DailyLog.find().lean(), Sale.find().lean(),
    Laborer.find().lean(), LaborAttendance.find().lean(), LaborAdvance.find().lean(), Supplier.find().lean(), SupplierPayment.find().lean(), BreedingEvent.find().lean(),
  ]);
  const farms = await Farm.find().lean();
  return {
    farms,
    exportDate: new Date().toISOString(),
    farmName: 'Usman Dairy Farm',
    version: 3,
    cows, milk, expenses, rates, health, buyers, buyerPayments, rateHistory, dailyLogs, sales, laborers, laborAttendance, laborAdvances, suppliers, supplierPayments, breedingEvents, archiveJobs: await ArchiveJob.find().lean(), archiveRecords: await ArchiveRecord.find().lean(),
  };
}

function currentAutoBackupName(now = new Date()) {
  return `auto-${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;
}

async function maybeRunMonthlyAutoBackup(force = false) {
  const name = currentAutoBackupName();
  const existing = await Meta.findOne({ key: MONTHLY_AUTO_BACKUP_KEY });
  const value = (existing && existing.value) || {};
  if (!force && value.name === name && value.payload) return value;
  const stored = {
    name,
    createdAt: new Date().toISOString(),
    payload: await collectBackupPayload(),
  };
  await Meta.findOneAndUpdate(
    { key: MONTHLY_AUTO_BACKUP_KEY },
    { $set: { key: MONTHLY_AUTO_BACKUP_KEY, value: stored } },
    { upsert: true, new: true }
  );
  console.log(`💾 [Auto Backup] Saved ${name}`);

  // Silently email the snapshot to the admin so a copy lives OUTSIDE the
  // database. Failures never block the backup itself.
  try {
    if (mailConfigured()) {
      const admin = await User.findOne({ role: { $in: MUF_FULL_ROLE_VALUES }, email: { $nin: [null, ''] } });
      if (admin && admin.email) {
        await sendMail({
          to: admin.email,
          subject: `Usman Dairy Farm — monthly backup ${name}`,
          text: `Attached is the automatic monthly backup (${name}) of Usman Dairy Farm.`,
          html: mufEmail({
            title: `Monthly backup — ${name}`,
            bodyHtml: `<p style="margin:0;">Attached is the automatic monthly backup (<strong>${name}</strong>) of Usman Dairy Farm. Keep this file safe — it can restore all farm data.</p>`,
          }),
          attachments: [{
            filename: `${name}-dairyfarm-backup.json`,
            content: JSON.stringify(stored.payload, null, 2),
            contentType: 'application/json',
          }],
        });
        stored.emailedTo = admin.email;
        stored.emailedAt = new Date().toISOString();
        await Meta.findOneAndUpdate(
          { key: MONTHLY_AUTO_BACKUP_KEY },
          { $set: { 'value.emailedTo': stored.emailedTo, 'value.emailedAt': stored.emailedAt } }
        );
        console.log(`📧 [Auto Backup] Emailed ${name} to ${admin.email}`);
      }
    }
  } catch (mailErr) {
    console.error('[Auto Backup] Email failed:', mailErr.message);
  }
  return stored;
}

// GET /api/backup/auto — info + payload of the stored monthly auto-backup
router.get('/auto', protectUnscoped, ...adminOnly, async (_req, res) => {
  try {
    const existing = await Meta.findOne({ key: MONTHLY_AUTO_BACKUP_KEY });
    const value = (existing && existing.value) || null;
    if (!value || !value.payload) return res.json({ available: false });
    res.json({ available: true, name: value.name, createdAt: value.createdAt, emailedTo: value.emailedTo || null, emailedAt: value.emailedAt || null, payload: value.payload });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// POST /api/backup/auto/run — force-refresh this month's snapshot now
router.post('/auto/run', protectUnscoped, ...adminOnly, async (_req, res) => {
  try {
    const stored = await maybeRunMonthlyAutoBackup(true);
    res.json({ ok: true, name: stored.name, createdAt: stored.createdAt });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// POST /api/backup/restore-auto — restore the DB from the monthly auto-backup
router.post('/restore-auto', protectUnscoped, ...adminOnly, async (_req, res) => {
  try {
    const existing = await Meta.findOne({ key: MONTHLY_AUTO_BACKUP_KEY });
    const value = (existing && existing.value) || null;
    if (!value || !value.payload) return res.status(404).json({ error: 'No auto-backup available yet' });
    validateBackupPayload(value.payload);
    await restoreMissingFarms(value.payload);
    await restoreCollections(value.payload, null);
    await tagAfterRestore();
    res.json({ success: true, message: `Restored from ${value.name}` });
  } catch (e) { res.status(500).json({ error: `Restore failed: ${e.message}` }); }
});

export default router;
export { maybeRunMonthlyAutoBackup };

import express from 'express';
import { randomUUID } from 'node:crypto';
import { protect, adminOnly } from '../middleware/auth.js';
import { Cow, BreedingEvent } from '../db.js';
import { readString, readDate, readEnum, sendValidationError } from './input.js';

const router = express.Router();
const TYPES = ['heat', 'service', 'pregnancy_check', 'calving'];
const SIRE_SOURCES = ['farm_bull', 'outside_bull', 'outside_straw'];
const TEXT_LIMITS = { technician: 120, result: 500, notes: 2000, bullName: 160, semenCode: 100 };

function eventPayload(body, { partial = false } = {}) {
  const errors = [];
  const payload = {};
  const required = !partial;
  const cowId = readString(body, 'cowId', errors, { required, allowEmpty: false });
  if (cowId !== undefined) payload.cowId = cowId;
  const type = readEnum(body, 'type', TYPES, errors, { required });
  if (type !== undefined) payload.type = type;
  const date = readDate(body, 'date', errors, { required });
  if (date !== undefined) payload.date = date;

  const sireSource = readEnum(body, 'sireSource', SIRE_SOURCES, errors);
  if (sireSource !== undefined) payload.sireSource = sireSource;
  for (const field of Object.keys(TEXT_LIMITS)) {
    const value = readString(body, field, errors);
    if (value !== undefined) {
      if (value.length > TEXT_LIMITS[field]) errors.push(`${field} must be at most ${TEXT_LIMITS[field]} characters`);
      else payload[field] = value;
    }
  }
  const bullId = readString(body, 'bullId', errors);
  if (bullId !== undefined) payload.bullId = bullId;
  if (payload.sireSource === 'farm_bull' && !payload.bullId && required) errors.push('bullId is required for an in-farm bull');
  if (payload.sireSource === 'outside_bull' && !payload.bullName && required) errors.push('bullName is required for an outside bull');
  if (payload.sireSource === 'outside_straw') {
    if (!payload.bullName && required) errors.push('bullName is required for outside straw');
    if (!payload.semenCode && required) errors.push('semenCode is required for outside straw');
  }
  if (body.calves !== undefined) {
    if (!Array.isArray(body.calves) || body.calves.length > 4) {
      errors.push('calves must be a list with no more than four entries');
    } else {
      payload.calves = body.calves.map((entry, index) => {
        const gender = entry?.gender === 'male' ? 'male' : entry?.gender === 'female' ? 'female' : '';
        const outcome = entry?.outcome === 'stillbirth' ? 'stillbirth' : entry?.outcome === 'live' || entry?.outcome === undefined ? 'live' : '';
        const earTag = typeof entry?.earTag === 'string' ? entry.earTag.trim().slice(0, 80) : '';
        if (!gender) errors.push(`calves[${index}].gender must be female or male`);
        if (!outcome) errors.push(`calves[${index}].outcome must be live or stillbirth`);
        return { gender: gender || 'female', outcome: outcome || 'live', earTag };
      });
      const tags = payload.calves.map((entry) => entry.earTag.toLocaleLowerCase()).filter(Boolean);
      if (new Set(tags).size !== tags.length) errors.push('Calf ear tags must be unique within this calving event');
    }
  }
  if (payload.calves !== undefined && payload.calves.length > 0 && payload.type !== undefined && payload.type !== 'calving') {
    errors.push('Calf entries are only allowed on a calving event');
  }
  return { payload, errors };
}

async function validateReferences(payload, res) {
  if (payload.cowId !== undefined) {
    const cow = await Cow.findById(payload.cowId).lean();
    if (!cow) { res.status(400).json({ error: 'Cow not found in the selected farm' }); return false; }
    if (cow.gender === 'male' || cow.status === 'sold' || cow.status === 'inactive' || cow.status === 'calf' || cow.isCalf) {
      res.status(400).json({ error: 'Breeding events require an active female animal, not a bull, sold animal or calf' });
      return false;
    }
  }
  if (payload.sireSource === 'farm_bull' && payload.bullId !== undefined) {
    const bull = await Cow.findById(payload.bullId).lean();
    if (!bull || bull.gender !== 'male' || bull.status === 'sold' || bull.status === 'calf' || bull.isCalf) {
      res.status(400).json({ error: 'In-farm sire must be a male animal in the selected farm' });
      return false;
    }
  }
  if (payload.sireSource && payload.sireSource !== 'farm_bull') payload.bullId = '';
  if (payload.sireSource === 'farm_bull') {
    payload.bullName = '';
    payload.semenCode = '';
  }
  if (payload.sireSource === 'outside_bull') payload.semenCode = '';
  return true;
}

function legacyField(type) {
  return ({ heat: 'heatDate', service: 'pregnancyDate', calving: 'calvingDate' })[type] || null;
}

async function syncCowDate(cowId, type) {
  const field = legacyField(type);
  if (!field || !cowId) return;
  const latest = await BreedingEvent.findOne({ cowId, type }).sort({ date: -1, createdAt: -1 }).lean();
  const cow = await Cow.findById(cowId).lean();
  if (!cow) return;
  const patch = {};
  // Preserve a legacy date when no event remains; deleting new event history must not erase older cow data.
  if (latest) patch[field] = latest.date;
  if (Object.keys(patch).length) await Cow.findByIdAndUpdate(cowId, { $set: patch });
}

function pagination(query) {
  const rawPage = query.page === undefined ? '1' : String(query.page);
  const rawLimit = query.limit === undefined ? '50' : String(query.limit);
  if (!/^\d+$/.test(rawPage) || Number(rawPage) < 1 || !Number.isSafeInteger(Number(rawPage))) return { error: 'page must be a positive integer' };
  if (!/^\d+$/.test(rawLimit) || Number(rawLimit) < 1) return { error: 'limit must be a positive integer' };
  const page = Number(rawPage);
  const limit = Math.min(Number(rawLimit), 200);
  return { page, limit, skip: (page - 1) * limit };
}

// Preserve GET /api/breeding: existing calendar and reminder contract.
router.get('/events', protect, async (req, res) => {
  try {
    const pg = pagination(req.query);
    if (pg.error) return res.status(400).json({ error: pg.error });
    const filter = {};
    if (req.query.cowId !== undefined) filter.cowId = String(req.query.cowId);
    if (req.query.type !== undefined) {
      if (!TYPES.includes(String(req.query.type))) return res.status(400).json({ error: 'Invalid event type' });
      filter.type = String(req.query.type);
    }
    for (const key of ['from', 'to']) {
      if (req.query[key] !== undefined) {
        const probe = readDate({ date: String(req.query[key]) }, 'date', []);
        if (probe === undefined) return res.status(400).json({ error: `${key} must be a valid YYYY-MM-DD date` });
      }
    }
    if (req.query.from || req.query.to) {
      filter.date = {};
      if (req.query.from) filter.date.$gte = String(req.query.from);
      if (req.query.to) filter.date.$lte = String(req.query.to);
    }
    const [events, total] = await Promise.all([
      BreedingEvent.find(filter).sort({ date: -1, _id: -1 }).skip(pg.skip).limit(pg.limit).lean(),
      BreedingEvent.countDocuments(filter),
    ]);
    res.json({ events, total, page: pg.page, limit: pg.limit, pages: Math.ceil(total / pg.limit) });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

async function createCalvingCalves(event, mother, farmId) {
  const entries = Array.isArray(event.calves) ? event.calves : [];
  const created = [];
  try {
    for (const entry of entries) {
      if (entry.outcome === 'stillbirth') continue;
      const earTag = String(entry.earTag || '').trim().toLocaleUpperCase();
      if (earTag) {
        // Be explicit about the selected farm instead of relying only on the
        // request-scoped model wrapper. This keeps the rule obvious and makes
        // identical ear tags valid in separate farms in both Mongo and memory mode.
        const taggedCows = await Cow.find({ farmId, earTag: { $ne: '' } }).lean();
        const normalizedTag = earTag.toLocaleLowerCase();
        const duplicate = taggedCows.some((cow) => String(cow.earTag || '').trim().toLocaleLowerCase() === normalizedTag);
        if (duplicate) throw Object.assign(new Error(`Ear tag "${earTag}" is already used in this farm`), { status: 409 });
      }
      const id = randomUUID();
      const name = earTag ? `Calf ${earTag}` : `${mother.name} calf ${event.date} ${created.length + 1}`;
      const fatherType = event.sireSource === 'farm_bull' ? 'farm' : (event.sireSource ? 'outside' : '');
      const calf = await Cow.create({
        _id: id,
        name,
        breed: mother.breed || 'Unknown',
        gender: entry.gender,
        status: 'calf',
        isCalf: true,
        birthDate: event.date,
        earTag,
        motherId: mother._id,
        fatherId: event.sireSource === 'farm_bull' ? event.bullId || '' : '',
        fatherType: fatherType || 'farm',
        fatherName: event.sireSource && event.sireSource !== 'farm_bull'
          ? [event.bullName, event.semenCode].filter(Boolean).join(' / ')
          : '',
        calvingEventId: event._id,
      });
      created.push(calf);
    }
    return created;
  } catch (error) {
    await Promise.all(created.map((calf) => Cow.findByIdAndDelete(calf._id).catch(() => null)));
    throw error;
  }
}

router.post('/events', protect, async (req, res) => {
  let event = null;
  let createdCalves = [];
  try {
    const { payload, errors } = eventPayload(req.body || {});
    if (errors.length) return sendValidationError(res, errors);
    if (!(await validateReferences(payload, res))) return;
    const mother = await Cow.findById(payload.cowId).lean();
    if (payload.type === 'calving' && !Array.isArray(payload.calves)) {
      payload.calves = [];
    }
    event = await BreedingEvent.create({ ...payload, generatedCalfIds: [], _id: randomUUID() });
    if (event.type === 'calving' && event.calves.length) {
      createdCalves = await createCalvingCalves(event, mother, req.farmContext?.farmId || event.farmId);
      const generatedCalfIds = createdCalves.map((calf) => calf._id);
      event = await BreedingEvent.findByIdAndUpdate(event._id, { $set: { generatedCalfIds } }, { new: true });
    }
    await syncCowDate(event.cowId, event.type);
    res.status(201).json(event);
  } catch (e) {
    await Promise.all(createdCalves.map((calf) => Cow.findByIdAndDelete(calf._id).catch(() => null)));
    if (event?._id) await BreedingEvent.findByIdAndDelete(event._id).catch(() => null);
    res.status(e.status || (e.code === 11000 ? 409 : 500)).json({ error: e.code === 11000 ? 'That ear tag is already used in this farm' : e.message });
  }
});

router.put('/events/:id', protect, async (req, res) => {
  try {
    const existing = await BreedingEvent.findById(req.params.id).lean();
    if (!existing) return res.status(404).json({ error: 'Breeding event not found' });
    const { payload: changes, errors: changeErrors } = eventPayload(req.body || {}, { partial: true });
    if (changeErrors.length) return sendValidationError(res, changeErrors);
    const next = { ...existing, ...changes };
    const { payload, errors } = eventPayload(next);
    if (errors.length) return sendValidationError(res, errors);
    if (!(await validateReferences(payload, res))) return;
    if (existing.type === 'calving' && (existing.generatedCalfIds || []).length) {
      const protectedFields = ['cowId', 'date', 'sireSource', 'bullId', 'bullName', 'semenCode'];
      const changedCoreData = protectedFields.some((field) =>
        String(payload[field] ?? existing[field] ?? '') !== String(existing[field] ?? '')
      );
      const normalizeCalves = (entries) => (entries || []).map((entry) => ({
        gender: entry.gender,
        earTag: String(entry.earTag || '').trim(),
        outcome: entry.outcome || 'live',
      }));
      const changedCalfEntries = JSON.stringify(normalizeCalves(payload.calves ?? existing.calves)) !== JSON.stringify(normalizeCalves(existing.calves));
      const changedGeneratedData = changedCoreData || changedCalfEntries;
      if (changedGeneratedData) {
        return res.status(409).json({ error: 'This calving already has generated calves. Calf identity, date and sire cannot be changed; create a correction workflow instead.' });
      }
    }
    const updated = await BreedingEvent.findByIdAndUpdate(req.params.id, { $set: payload }, { new: true });
    await syncCowDate(existing.cowId, existing.type);
    await syncCowDate(next.cowId, next.type);
    res.json(updated);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

router.delete('/events/:id', protect, adminOnly, async (req, res) => {
  try {
    const event = await BreedingEvent.findById(req.params.id).lean();
    if (!event) return res.status(404).json({ error: 'Breeding event not found' });
    if (event.type === 'calving' && (event.generatedCalfIds || []).length) {
      return res.status(409).json({ error: 'This calving has linked calf records. Resolve the calf records before deleting the event.' });
    }
    await BreedingEvent.findByIdAndDelete(req.params.id);
    await syncCowDate(event.cowId, event.type);
    res.json({ deleted: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

