/**
 * Validate incubation egg allocations against batch egg logs for the active farm.
 * Inputs must already be loaded through the farm-scoped model context.
 */
export function validateIncubationAllocations(records, batches, eggLogs) {
  if (!Array.isArray(records)) return 'Incubation data must be an array.';

  const linkedIds = new Set(
    records.map((record) => String(record?.sourceBatchId || '').trim()).filter(Boolean),
  );
  if (linkedIds.size === 0) return null;

  const batchById = new Map(batches.map((batch) => [String(batch.batch_id), batch]));
  for (const batchId of linkedIds) {
    if (!batchById.has(batchId)) {
      return `Source batch "${batchId}" was not found in the selected farm.`;
    }
  }

  const availableByBatch = new Map();
  for (const batchId of linkedIds) availableByBatch.set(batchId, 0);
  for (const log of eggLogs) {
    const batchId = String(log.batch_id);
    if (!availableByBatch.has(batchId)) continue;
    // A malformed legacy row contributes no usable supply; NaN must never
    // bypass the allocation comparison, and negative counts cannot inflate stock.
    const counts = ['collected', 'sold', 'home_use', 'broken_wasted'].map((field) => {
      const raw = log[field];
      if (raw === undefined || raw === null || raw === '') return 0;
      const count = Number(raw);
      return Number.isSafeInteger(count) && count >= 0 ? count : NaN;
    });
    if (counts.some((count) => !Number.isSafeInteger(count))) continue;
    const [collected, sold, homeUse, brokenWasted] = counts;
    const net = collected - sold - homeUse - brokenWasted;
    availableByBatch.set(batchId, availableByBatch.get(batchId) + Math.max(0, net));
  }

  const allocatedByBatch = new Map();
  for (const record of records) {
    const batchId = String(record?.sourceBatchId || '').trim();
    if (!batchId) continue;
    const eggsSet = Number(record.eggsSet);
    if (!Number.isInteger(eggsSet) || eggsSet <= 0) {
      return `Incubation record ${record.id ?? '(new)'} must have a positive whole-number eggsSet count when linked to a batch.`;
    }
    allocatedByBatch.set(batchId, (allocatedByBatch.get(batchId) || 0) + eggsSet);
  }

  for (const batchId of linkedIds) {
    const available = availableByBatch.get(batchId) || 0;
    const allocated = allocatedByBatch.get(batchId) || 0;
    if (allocated > available) {
      return `Batch "${batchId}" has ${available} available eggs after sales, home use and waste, but incubation records allocate ${allocated}.`;
    }
  }
  return null;
}

// DEV-ONLY in-memory database backend.
//
// Activated ONLY when MEMORY_DB=true and no MONGODB_URI is set (see db.js).
// It patches mongoose.model() so every model in the app runs against plain
// in-process arrays instead of a real MongoDB — data lives until restart.
// Production/Replit (with MONGODB_URI) never touches this file's logic.
//
// It implements just the subset of the Mongoose API this app uses:
//   find / findOne / findById (+ .sort/.select chaining)
//   findOneAndUpdate / findByIdAndDelete / create / insertMany
//   countDocuments / deleteMany / updateMany
//   doc.save / doc.validate / doc.deleteOne / doc.toObject
//   schema statics & methods, defaults, timestamps, required/enum validation
//   query operators: $or, $ne, $gt, $exists, $in
//   update operators: $set, $inc
//
// The pure query/match/update engine lives in the shared muf twin
// (../muf-query.mjs — same byte-identical file in all three backends),
// wired with the flock dialect: loose (string-tolerant) equality and
// nulls-last sorting.

import mongoose from 'mongoose';
import {
  mufNewId as newObjectId,
  mufGetPath as getPath,
  mufEq as eq,
  mufMatchValue,
  mufMatches,
  mufSort,
  mufApplyUpdate as applyUpdate,
} from './muf-query.mjs';

// flock dialect: numbers and string ids compare by String()
function matchValue(docVal, cond) {
  return mufMatchValue(docVal, cond, { loose: true });
}

function matches(doc, filter = {}) {
  return mufMatches(doc, filter, { loose: true });
}

function sortDocs(docs, spec) {
  return mufSort(docs, spec, { nullsLast: true });
}

class Query {
  constructor(exec) {
    this._exec = exec;
    this._sort = null;
    this._skip = 0;
    this._limit = null;
  }
  sort(spec) { this._sort = spec; return this; }
  select() { return this; }
  skip(count) { this._skip = Math.max(0, Number(count) || 0); return this; }
  limit(count) { this._limit = Math.max(0, Number(count) || 0); return this; }
  lean() { return this; }
  then(resolve, reject) {
    try {
      let result = this._exec(this._sort);
      if (Array.isArray(result)) {
        result = result.slice(this._skip, this._limit == null ? undefined : this._skip + this._limit);
      }
      return Promise.resolve(result).then(resolve, reject);
    } catch (err) { return Promise.reject(err).then(resolve, reject); }
  }
  catch(fn) { return this.then((v) => v, fn); }
}

function duplicateKeyError(field) {
  const err = new Error(`E11000 duplicate key error (memory db): ${field}`);
  err.code = 11000;
  return err;
}

export function makeMemoryModel(name, schema) {
  const store = [];
  const paths = [];
  schema.eachPath((p, type) => {
    if (p === '_id' || p === '__v') return;
    paths.push({ path: p, options: type.options || {}, type });
  });
  const timestamps = !!(schema.options && schema.options.timestamps);
  const uniquePaths = paths
    .filter((p) => p.options.unique === true || (p.options.index && p.options.index.unique === true))
    .map((p) => p.path);

  class MemoryDoc {
    constructor(fields = {}) {
      Object.assign(this, fields);
      if (!this._id) this._id = newObjectId();
      for (const { path, options } of paths) {
        if (getPath(this, path) === undefined && options.default !== undefined && !path.includes('.')) {
          this[path] = typeof options.default === 'function' ? options.default() : options.default;
        }
      }
      if (timestamps) {
        if (!this.createdAt) this.createdAt = new Date();
        if (!this.updatedAt) this.updatedAt = new Date();
      }
    }

    async validate() {
      for (const { path, options } of paths) {
        if (path.includes('.')) continue;
        const value = this[path];
        const required = Array.isArray(options.required) ? options.required[0] : options.required;
        if (required && (value === undefined || value === null || value === '')) {
          throw new Error(`Path \`${path}\` is required.`);
        }
        if (options.enum && Array.isArray(options.enum) && value != null && !options.enum.includes(value)) {
          throw new Error(`\`${value}\` is not a valid enum value for path \`${path}\`.`);
        }
        if (typeof options.min === 'number' && typeof value === 'number' && value < options.min) {
          throw new Error(`Path \`${path}\` (${value}) is less than minimum allowed value (${options.min}).`);
        }
        if (typeof options.minlength === 'number' && typeof value === 'string' && value.length < options.minlength) {
          throw new Error(`Path \`${path}\` is shorter than the minimum allowed length (${options.minlength}).`);
        }
      }
    }

    _checkUnique() {
      for (const field of uniquePaths) {
        const value = this[field];
        if (value === undefined || value === null) continue;
        const clash = store.find((d) => d !== this && eq(d[field], value));
        if (clash) throw duplicateKeyError(field);
      }
    }

    async save() {
      if (timestamps) this.updatedAt = new Date();
      await this.validate();
      this._checkUnique();
      if (!store.includes(this)) store.push(this);
      return this;
    }

    async deleteOne() {
      const i = store.indexOf(this);
      if (i >= 0) store.splice(i, 1);
      return this;
    }

    toObject() { return JSON.parse(JSON.stringify({ ...this }, bufferSafe)); }
    toJSON() { return this.toObject(); }
  }

  // Buffers must survive toObject for the Image model
  function bufferSafe(_key, value) { return value; }
  MemoryDoc.prototype.toObject = function toObject() {
    const out = {};
    for (const [k, v] of Object.entries(this)) out[k] = v;
    return out;
  };
  MemoryDoc.prototype.toJSON = MemoryDoc.prototype.toObject;

  Object.assign(MemoryDoc.prototype, schema.methods || {});

  const Model = {
    modelName: name,
    _store: store,

    find(filter = {}) {
      return new Query((sort) => sortDocs(store.filter((d) => matches(d, filter)), sort));
    },
    findOne(filter = {}) {
      return new Query((sort) => sortDocs(store.filter((d) => matches(d, filter)), sort)[0] || null);
    },
    findById(id) {
      return new Query(() => store.find((d) => eq(d._id, id)) || null);
    },
    async countDocuments(filter = {}) {
      return store.filter((d) => matches(d, filter)).length;
    },
    async create(fields) {
      const doc = new MemoryDoc(fields);
      await doc.save();
      return doc;
    },
    async insertMany(items) {
      const docs = [];
      for (const item of items) {
        const doc = item instanceof MemoryDoc ? item : new MemoryDoc(item);
        await doc.save();
        docs.push(doc);
      }
      return docs;
    },
    async deleteOne(filter = {}) {
      const idx = store.findIndex((doc) => matches(doc, filter));
      if (idx === -1) return { deletedCount: 0 };
      store.splice(idx, 1);
      return { deletedCount: 1 };
    },
    async deleteMany(filter = {}) {
      const keep = store.filter((d) => !matches(d, filter));
      const deletedCount = store.length - keep.length;
      store.length = 0;
      store.push(...keep);
      return { deletedCount };
    },
    async updateMany(filter, update) {
      let n = 0;
      for (const doc of store) {
        if (matches(doc, filter)) { applyUpdate(doc, update); n += 1; }
      }
      return { modifiedCount: n };
    },
    async findOneAndUpdate(filter, update, options = {}) {
      const doc = store.find((d) => matches(d, filter));
      if (!doc) {
        if (options.upsert) {
          const base = {};
          for (const [k, v] of Object.entries(filter)) if (!k.startsWith('$')) base[k] = v;
          const fresh = new MemoryDoc(base);
          applyUpdate(fresh, update);
          await fresh.save();
          return fresh;
        }
        return null;
      }
      applyUpdate(doc, update);
      if (timestamps) doc.updatedAt = new Date();
      return doc;
    },
    async findByIdAndUpdate(id, update, options = {}) {
      const doc = store.find((d) => eq(d._id, id));
      if (!doc) return null;
      applyUpdate(doc, update);
      if (timestamps) doc.updatedAt = new Date();
      return doc;
    },
    async findOneAndDelete(filter = {}) {
      const doc = store.find((d) => matches(d, filter));
      if (doc) await doc.deleteOne();
      return doc || null;
    },
    async findByIdAndDelete(id) {
      const doc = store.find((d) => eq(d._id, id));
      if (doc) await doc.deleteOne();
      return doc || null;
    },
  };

  Object.assign(Model, schema.statics || {});
  return Model;
}

export function enableMemoryDb() {
  const registry = new Map();
  mongoose.model = function patchedModel(name, schema) {
    if (registry.has(name)) return registry.get(name);
    if (!schema) throw new Error(`Memory DB: model "${name}" requested before registration`);
    const model = makeMemoryModel(name, schema);
    registry.set(name, model);
    return model;
  };
  console.warn('⚠️  MEMORY_DB mode: using in-process data store — all data is lost on restart. NEVER use in production.');
}

// Binary-safe serialization for Flock image backups. JSON does not preserve Buffer objects,
// so exports carry a canonical base64 representation and restore converts it back to bytes.
function toBuffer(value) {
  if (Buffer.isBuffer(value)) return Buffer.from(value);
  if (value instanceof Uint8Array) return Buffer.from(value);
  if (value && typeof value.value === 'function') return Buffer.from(value.value(true));
  if (value && value.type === 'Buffer' && Array.isArray(value.data)) return Buffer.from(value.data);
  throw new TypeError('Image backup row is missing binary image data.');
}

export function serializeBackupImages(images) {
  if (!Array.isArray(images)) throw new TypeError('Images must be an array.');
  return images.map((source) => {
    const image = source && typeof source.toObject === 'function' ? source.toObject() : source;
    if (!image || typeof image !== 'object' || !image._id) {
      throw new TypeError('Every image backup row must have an ID.');
    }
    const { data, __v, ...metadata } = image;
    return {
      ...metadata,
      _id: String(image._id),
      farmId: String(image.farmId || ''),
      dataBase64: toBuffer(data).toString('base64'),
    };
  });
}

export function restoreBackupImages(rows) {
  if (!Array.isArray(rows)) throw new TypeError('Image backup section must be an array.');
  return rows.map((source, index) => {
    if (!source || typeof source !== 'object' || Array.isArray(source)) {
      throw new TypeError(`Image backup row ${index + 1} must be an object.`);
    }
    if (source._id === undefined || source._id === null || !String(source._id).trim()) {
      throw new TypeError(`Image backup row ${index + 1} is missing its ID.`);
    }
    if (source.farmId === undefined || source.farmId === null || !String(source.farmId).trim()) {
      throw new TypeError(`Image backup row ${index + 1} is missing its farm ID.`);
    }
    if (typeof source.dataBase64 !== 'string') {
      throw new TypeError(`Image backup row ${index + 1} has invalid base64 data.`);
    }
    // Decode/round-trip validation handles huge valid strings without a regex stack overflow.
    const data = Buffer.from(source.dataBase64, 'base64');
    if (data.toString('base64') !== source.dataBase64) {
      throw new TypeError(`Image backup row ${index + 1} has invalid base64 data.`);
    }
    const { dataBase64, __v, ...metadata } = source;
    return { ...metadata, _id: String(source._id), farmId: String(source.farmId), data };
  });
}

export function splitBase64Image(image, imageIndex, chunkChars) {
  if (!Number.isInteger(chunkChars) || chunkChars < 4 || chunkChars % 4 !== 0) {
    throw new TypeError('Image chunk size must be a positive multiple of four.');
  }
  const { dataBase64, ...metadata } = image;
  if (typeof dataBase64 !== 'string') throw new TypeError('Serialized image is missing base64 data.');
  const partCount = Math.max(1, Math.ceil(dataBase64.length / chunkChars));
  return Array.from({ length: partCount }, (_, partIndex) => ({
    imageIndex,
    imageId: String(image._id),
    partIndex,
    partCount,
    metadata: partIndex === 0 ? metadata : null,
    dataBase64Part: dataBase64.slice(partIndex * chunkChars, (partIndex + 1) * chunkChars),
  }));
}

export function assembleBase64ImageParts(parts, expectedImageIndex) {
  if (!Array.isArray(parts) || parts.length === 0) throw new TypeError('Image backup is missing data chunks.');
  const sorted = [...parts].sort((a, b) => a.partIndex - b.partIndex);
  const count = sorted[0].partCount;
  if (!Number.isInteger(count) || count < 1 || sorted.length !== count) throw new TypeError('Image backup has missing data chunks.');
  for (let i = 0; i < count; i += 1) {
    if (sorted[i].partIndex !== i || sorted[i].partCount !== count || sorted[i].imageIndex !== expectedImageIndex) {
      throw new TypeError('Image backup has inconsistent data chunks.');
    }
  }
  if (!sorted[0].metadata || typeof sorted[0].metadata !== 'object') throw new TypeError('Image backup is missing metadata.');
  return { ...sorted[0].metadata, dataBase64: sorted.map((part) => part.dataBase64Part).join('') };
}

/* ═══════════════════════════════════════════════════════════════
   muf-card — the shared public "card page" renderer for all three
   farm backends. Renders a standalone, no-login HTML page (the
   QR card a worker / buyer / supplier opens on their phone) in the
   premium muf card format:
     • rounded card with dot-texture corners + green corner accents
     • farm identity header (round logo, farm name, dash-flanked
       uppercase subtitle) — same identity rules in all 3 apps
     • green title badge with golden month + Urdu title side box
     • rows with dark-green icon tiles — English label on top,
       Urdu below; value on the right, Urdu value below it
     • highlighted balance band (calculator icon + money bag)
     • shield footer note (English left, Urdu right)
     • "THANK YOU! / شکریہ" pill with the farm logo

