/* ── small shared helpers for card builders ──────────────────────────────── */

const URDU_MONTHS = ['جنوری','فروری','مارچ','اپریل','مئی','جون','جولائی','اگست','ستمبر','اکتوبر','نومبر','دسمبر'];

/** '2026-08' → { en: 'August 2026', ur: 'اگست 2026' } */
export function mufCardMonth(monthKeyStr) {
  const [y, m] = String(monthKeyStr || '').split('-').map(Number);
  if (!y || !m) return { en: '', ur: '' };
  const en = new Date(y, m - 1, 1).toLocaleString('en', { month: 'long' }) + ' ' + y;
  return { en, ur: `${URDU_MONTHS[m - 1]} ${y}` };
}

/** Rs formatting for card values. */
export function mufCardRs(n) {
  const v = Math.round(Number(n) || 0);
  return 'Rs ' + v.toLocaleString('en-PK');
}
/** روپیہ formatting (Urdu line). */
export function mufCardRsUr(n) {
  const v = Math.round(Number(n) || 0);
  return 'روپے ' + v.toLocaleString('en-PK');
}

/* ═══════════════════════════════════════════════════════════════
   muf-env — the ONE place the three farm backends read env vars.
   Canonical names are the SAME across dairy / flock / agri:

     MONGO_URI  JWT_SECRET  APP_URL  FRONTEND_URL
     SMTP_HOST  SMTP_PORT  SMTP_SECURE  SMTP_USER  SMTP_PASS  SMTP_FROM
     TELEGRAM_BOT_TOKEN  TELEGRAM_WEBHOOK_SECRET
     CRON_SECRET  MEMORY_MODE  CROSS_FARM_KEY  TZ_OFFSET_HOURS  LOG_REQUESTS
     CLOUDINARY_CLOUD_NAME  CLOUDINARY_API_KEY  CLOUDINARY_API_SECRET
     PORT (per-app: 3000 / 3001 / 8000)

   Legacy aliases keep old .env files working (see pick() calls).
   Keep this file byte-identical in all three backends.
   ═══════════════════════════════════════════════════════════════ */
const env = process.env;

/** First non-empty value among the given env var names (canonical first). */
function pick(...names) {
  for (const n of names) {
    const v = env[n];
    if (v !== undefined && String(v).trim() !== '') return v;
  }
  return undefined;
}

/** Comma-separated env value → trimmed list (['a', 'b']). */
export function mufEnvList(value) {
  return String(value || '').split(',').map((s) => s.trim()).filter(Boolean);
}

// Normalize numeric token lifetimes consistently across all three apps.
// JWT libraries interpret unitless strings as milliseconds, but this project
// documents bare numeric values as minutes. Preserve explicit units (7d, 30m).
function normalizeJwtExpiresIn(value) {
  if (value === undefined || value === null || String(value).trim() === '') return undefined;
  const raw = String(value).trim();
  return /^\d+$/.test(raw) ? raw + 'm' : raw;
}

export const MUF_ENV = {
  nodeEnv: env.NODE_ENV || '',

  // ── Database ─
  /** Canonical MONGO_URI (legacy alias: MONGODB_URI). */
  mongoUri: pick('MONGO_URI', 'MONGODB_URI'),
  /** In-memory demo mode (legacy alias: ALLOW_MEMORY_MODE). */
  memoryMode: pick('MEMORY_MODE', 'ALLOW_MEMORY_MODE') === '1',

  // ── Auth ──
  /** Canonical JWT_SECRET (legacy aliases: SECRET_KEY, SESSION_SECRET). */
  jwtSecret: pick('JWT_SECRET', 'SECRET_KEY', 'SESSION_SECRET'),
  jwtExpiresIn: normalizeJwtExpiresIn(pick('JWT_EXPIRES_IN')),
  bcryptRounds: pick('BCRYPT_SALT_ROUNDS'),

  // ── Server ──
  port: pick('PORT'),
  appUrl: pick('APP_URL', 'BASE_URL'),
  /** CORS origins — canonical FRONTEND_URL (legacy alias: CORS_ORIGIN),
   *  comma-separated, may be several. */
  corsOrigins: mufEnvList(pick('FRONTEND_URL', 'CORS_ORIGIN')),

  // ── Email ─ (legacy aliases: EMAIL_HOST/PORT/USER/PASS)
  smtpHost: pick('SMTP_HOST', 'EMAIL_HOST'),
  smtpPort: pick('SMTP_PORT', 'EMAIL_PORT'),
  smtpSecure: pick('SMTP_SECURE'),
  smtpUser: pick('SMTP_USER', 'EMAIL_USER'),
  smtpPass: pick('SMTP_PASS', 'EMAIL_PASS'),
  /** Canonical SMTP_FROM (legacy aliases: SMTP_SENDER, MAIL_FROM). */
  smtpFrom: pick('SMTP_FROM', 'SMTP_SENDER', 'MAIL_FROM'),

  // ── Telegram ─
  telegramBotToken: pick('TELEGRAM_BOT_TOKEN'),
  telegramWebhookSecret: pick('TELEGRAM_WEBHOOK_SECRET'),

  // ── Cron + cross-farm ──
  cronSecret: pick('CRON_SECRET'),
  crossFarmKey: pick('CROSS_FARM_KEY'),

  // ── Optional photo storage ──
  cloudinaryCloudName: pick('CLOUDINARY_CLOUD_NAME'),
  cloudinaryApiKey: pick('CLOUDINARY_API_KEY'),
  cloudinaryApiSecret: pick('CLOUDINARY_API_SECRET'),

  // ── Diagnostics ──
  logRequests: pick('LOG_REQUESTS') === '1',
  tzOffsetHours: pick('TZ_OFFSET_HOURS'),

  // ── App-specific extras (same style, single home) ──
  dailySummaryEmails: mufEnvList(pick('DAILY_SUMMARY_EMAILS')),
  disableInternalScheduler: pick('DISABLE_INTERNAL_SCHEDULER') === '1',
  cookieSecure: pick('COOKIE_SECURE') === '1',
};

/**
 * Optional rate-limit ceiling for isolated automated tests only.
 * Ignored unless both MEMORY_MODE=1 and NODE_ENV=test; production and real
 * database runs always retain the caller's normal ceiling.
 */
export function mufTestRateLimitMax(defaultMax) {
  const raw = env.MUF_TEST_RATE_LIMIT_MAX;
  if (!MUF_ENV.memoryMode || MUF_ENV.nodeEnv !== 'test' || !/^\d+$/.test(String(raw || ''))) return defaultMax;
  const requested = Number(raw);
  return Number.isSafeInteger(requested) && requested > 0 ? Math.min(requested, 1000000) : defaultMax;
}

/** True when a real Mongo URI is configured (placeholder template URIs don't count). */
export function mufEnvHasMongo() {
  const uri = MUF_ENV.mongoUri;
  if (!uri) return false;
  if (/user:password|<.*>|YOUR_/.test(uri)) return false;
  return true;
}

// MUF farms core. This file is a byte-identical twin in all three backends
// (agri_farm, dairy_farm, flock_farm); tools/check-muf-sync.js enforces it.
//
// What it provides (see docs/FARMS_AND_ROLES.md):
//   - the three roles (owner, manager, worker) and the legacy "admin" mapping
//   - farm access resolution for a request (which farm is selected, which are allowed)
//   - server-side farm scoping of model queries, via a per-request AsyncLocalStorage
//     context, so a user can never read or write a farm they are not assigned to
//   - a farms router factory (list, create, rename, archive, restore, delete)
//   - an idempotent migration (Farm 1, tag old records, convert roles)
//
// It has no dependency on mongoose or express, so it works with both the real
// MongoDB models and the in-memory demo models.
import { AsyncLocalStorage } from 'node:async_hooks';

// ─── Roles ──────────────────────────────────────────────────────────────────
export const MUF_ROLES = ['owner', 'manager', 'worker'];

/** Legacy "admin" accounts become owners; anything unknown is a worker. */
export function mufNormalizeRole(role) {
  if (role === 'owner' || role === 'admin') return 'owner';
  if (role === 'manager') return 'manager';
  return 'worker';
}
export const mufIsOwner = (role) => mufNormalizeRole(role) === 'owner';
/** Owner or manager: full control inside the farms they can see. */
export const mufIsFullRole = (role) => mufNormalizeRole(role) !== 'worker';
/** Old frontends only understand admin/worker. Removed once all screens use farmRole. */
export const mufLegacyRole = (role) => (mufIsFullRole(role) ? 'admin' : 'worker');
/** Mongo filter matching every account that may reset a password by email. */
export const MUF_FULL_ROLE_VALUES = ['owner', 'manager', 'admin'];

// ─── Request context ────────────────────────────────────────────────────────
// null / undefined store = unscoped (system jobs, backups, migration).
const als = new AsyncLocalStorage();
let defaultFarmId = null;

export function mufRunWithFarmContext(ctx, fn) { return als.run(ctx, fn); }
export function mufRunUnscoped(fn) { return als.run(null, fn); }
export function mufGetFarmContext() { return als.getStore() || null; }
/** Farm that system jobs (cron, Telegram bot) create records in. */
export function mufSetDefaultFarmId(id) { defaultFarmId = id ? String(id) : null; }
export function mufGetDefaultFarmId() { return defaultFarmId; }

const sid = (v) => (v === undefined || v === null ? '' : String(v));
const byCreated = (a, b) => {
  const ta = new Date(a.createdAt || 0).getTime();
  const tb = new Date(b.createdAt || 0).getTime();
  return ta - tb || sid(a._id).localeCompare(sid(b._id));
};

/**
 * Decide which farm(s) a request may use. Pure function.
 *   user:      { role, farmIds }
 *   farms:     every farm document { _id, archived, createdAt }
 *   requested: the X-Farm-Id header ('' / undefined = default, 'all', or an id)
 * Returns { ok: true, ctx } or { ok: false, status, code, message }.
 */
export function mufResolveFarmAccess({ user, farms, requested }) {
  const role = mufNormalizeRole(user?.role);
  const sorted = [...(farms || [])].sort(byCreated);
  if (sorted.length === 0) {
    return { ok: false, status: 503, code: 'MIGRATION_REQUIRED', message: 'Farms are not set up yet. Run the farms migration first.' };
  }
  const active = sorted.filter((f) => !f.archived);
  const assigned = new Set((user?.farmIds || []).map(sid));
  const allowed = role === 'owner'
    ? sorted
    : active.filter((f) => assigned.has(sid(f._id)));
  if (allowed.length === 0) {
    return { ok: false, status: 403, code: 'NO_FARM_ACCESS', message: 'You are not assigned to any farm.' };
  }
  const allowedActive = allowed.filter((f) => !f.archived);
  const want = sid(requested).trim();

  const base = { role, userId: sid(user?._id || user?.id) };
  if (want === 'all') {
    const ids = (allowedActive.length ? allowedActive : allowed).map((f) => sid(f._id));
    return { ok: true, ctx: { ...base, mode: 'all', farmId: null, farmIds: ids } };
  }
  if (want) {
    const hit = allowed.find((f) => sid(f._id) === want);
    if (!hit) return { ok: false, status: 403, code: 'FARM_FORBIDDEN', message: 'You do not have access to that farm.' };
    return { ok: true, ctx: { ...base, mode: 'single', farmId: sid(hit._id), farmIds: [sid(hit._id)] } };
  }
  const def = allowedActive[0] || allowed[0];
  return { ok: true, ctx: { ...base, mode: 'single', farmId: sid(def._id), farmIds: [sid(def._id)] } };
}

// ─── Scoping ────────────────────────────────────────────────────────────────
/** Add the farm constraint to a query filter. The server's constraint always wins. */
export function mufScopeFilter(filter, ctx) {
  const f = filter && typeof filter === 'object' ? filter : {};
  const scope = ctx.mode === 'all'
    ? { farmId: { $in: ctx.farmIds } }
    : { farmId: ctx.farmId };
  if (Object.prototype.hasOwnProperty.call(f, 'farmId')) return { $and: [f, scope] };
  return { ...f, ...scope };
}

/** Remove any attempt to move a record to another farm from an update document. */
export function mufStripFarmId(update) {
  if (!update || typeof update !== 'object' || Array.isArray(update)) return update;
  const u = { ...update };
  delete u.farmId;
  for (const op of ['$set', '$unset', '$setOnInsert', '$inc', '$push', '$addToSet']) {
    if (u[op] && typeof u[op] === 'object' && 'farmId' in u[op]) {
      u[op] = { ...u[op] };
      delete u[op].farmId;
    }
  }
  return u;
}

function farmRequiredError() {
  const e = new Error('Select one farm before saving (All farms is read-only).');
  e.status = 400;
  e.code = 'FARM_REQUIRED';
  return e;
}

function stampDoc(doc) {
  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) return doc;
  const ctx = mufGetFarmContext();
  if (ctx) {
    // Inside a request the server's farm always wins over anything the client sent.
    if (ctx.mode !== 'single' || !ctx.farmId) throw farmRequiredError();
    return { ...doc, farmId: ctx.farmId };
  }
  // System job (cron, Telegram bot, restore): keep an existing farmId, else use the default farm.
  if (doc.farmId) return doc;
  return defaultFarmId ? { ...doc, farmId: defaultFarmId } : { ...doc };
}

const FILTER_FNS = [
  'find', 'findOne', 'findOneAndUpdate', 'findOneAndDelete', 'updateOne', 'updateMany',
  'deleteOne', 'deleteMany', 'countDocuments', 'distinct', 'exists',
];
// Operations that could bypass the scope; they are refused inside a scoped request.
const BLOCKED_FNS = ['aggregate', 'bulkWrite', 'replaceOne', 'findOneAndReplace', 'estimatedDocumentCount'];

/**
 * Make one model farm-aware. Works on real mongoose models and the memory-db models.
 * Inside a request every read, update and delete is limited to the selected farm(s),
 * and every create is stamped with the selected farm.
 */
export function mufScopeModel(model, name = 'model') {
  if (!model || model.__mufFarmScoped) return model;
  const orig = {};
  for (const fn of [...FILTER_FNS, 'findById', 'findByIdAndUpdate', 'findByIdAndDelete', 'create', 'insertMany']) {
    if (typeof model[fn] === 'function') orig[fn] = model[fn];
  }

  const hasUpdateFilterFn = (fn) => typeof orig[fn] === 'function';

  for (const fn of FILTER_FNS) {
    if (!hasUpdateFilterFn(fn)) continue;
    const isUpdate = fn === 'findOneAndUpdate' || fn === 'updateOne' || fn === 'updateMany';
    const isDistinct = fn === 'distinct';
    model[fn] = function scoped(...args) {
      const ctx = mufGetFarmContext();
      if (!ctx) return orig[fn].apply(model, args);
      if (isDistinct) {
        const [field, filter, ...rest] = args;
        return orig[fn].call(model, field, mufScopeFilter(filter, ctx), ...rest);
      }
      const [filter, second, ...rest] = args;
      if (isUpdate) {
        const opts = rest[0] || {};
        if (opts.upsert && ctx.mode !== 'single') throw farmRequiredError();
        return orig[fn].call(model, mufScopeFilter(filter, ctx), mufStripFarmId(second), ...rest);
      }
      return orig[fn].call(model, mufScopeFilter(filter, ctx), second, ...rest);
    };
  }

  if (orig.findById) {
    model.findById = function scopedFindById(id, ...rest) {
      if (!mufGetFarmContext()) return orig.findById.call(model, id, ...rest);
      return model.findOne({ _id: id }, ...rest);
    };
  }
  if (orig.findByIdAndUpdate) {
    model.findByIdAndUpdate = function scopedFindByIdAndUpdate(id, update, ...rest) {
      if (!mufGetFarmContext()) return orig.findByIdAndUpdate.call(model, id, update, ...rest);
      return model.findOneAndUpdate({ _id: id }, update, ...rest);
    };
  }
  if (orig.findByIdAndDelete) {
    model.findByIdAndDelete = function scopedFindByIdAndDelete(id, ...rest) {
      if (!mufGetFarmContext()) return orig.findByIdAndDelete.call(model, id, ...rest);
      // Keep the farm predicate and deletion in one atomic operation. A
      // separate scoped read followed by an unscoped delete has a move race.
      return model.findOneAndDelete({ _id: id }, ...rest);
    };
  }
  if (orig.create) {
    model.create = function scopedCreate(docs, ...rest) {
      const out = Array.isArray(docs) ? docs.map(stampDoc) : stampDoc(docs);
      return orig.create.call(model, out, ...rest);
    };
  }
  if (orig.insertMany) {
    model.insertMany = function scopedInsertMany(docs, ...rest) {
      return orig.insertMany.call(model, (docs || []).map(stampDoc), ...rest);
    };
  }
  for (const fn of BLOCKED_FNS) {
    if (typeof model[fn] !== 'function') continue;
    const real = model[fn];
    model[fn] = function blocked(...args) {
      if (mufGetFarmContext()) {
        throw new Error(`${name}.${fn}() is not farm-scoped; use find/update helpers or mufRunUnscoped.`);
      }
      return real.apply(model, args);
    };
  }
  model.__mufFarmScoped = true;
  return model;
}

/** Scope every model in `models` whose name is listed in `names`. */
export function mufScopeModels(models, names) {
  for (const n of names) mufScopeModel(models[n], n);
  return models;
}

// ─── Express glue ───────────────────────────────────────────────────────────
const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

function stripFarmIdFromBody(body) {
  if (!body || typeof body !== 'object') return;
  if (Array.isArray(body)) { body.forEach(stripFarmIdFromBody); return; }
  delete body.farmId;
}

/**
 * Call from the authentication middleware once req.user is set
 * ({ id, role, farmIds }). Resolves the farm for this request, rejects writes in
 * "All farms" mode, and runs the rest of the request inside the farm context.
 */
export async function mufApplyFarmContext(req, res, next, { Farm }) {
  try {
    const farms = await Farm.find({}).select('_id name archived createdAt').lean();
    const result = mufResolveFarmAccess({
      user: req.user,
      farms,
      requested: req.headers['x-farm-id'],
    });
    if (!result.ok) return res.status(result.status).json({ error: result.message, code: result.code });
    const ctx = result.ctx;
    if (ctx.mode === 'all' && !SAFE_METHODS.has(req.method)) {
      return res.status(400).json({ error: 'Select one farm before saving (All farms is read-only).', code: 'FARM_REQUIRED' });
    }
    stripFarmIdFromBody(req.body);
    req.farmContext = ctx;
    return mufRunWithFarmContext(ctx, () => next());
  } catch (err) {
    console.error('Farm context failed:', err);
    return res.status(500).json({ error: 'Farm check failed' });
  }
}

const cleanName = (v) => String(v ?? '').trim().replace(/\s+/g, ' ').slice(0, 80);
const cleanText = (v) => String(v ?? '').trim().slice(0, 200);
const farmJson = (f) => ({
  id: sid(f._id), _id: sid(f._id), name: f.name, location: f.location || '',
  archived: Boolean(f.archived), createdAt: f.createdAt,
});

/** Count the records of one farm across every farm-scoped model. */
export async function mufCountFarmRecords(models, names, farmId) {
  return mufRunUnscoped(async () => {
    const counts = {};
    let total = 0;
    for (const n of names) {
      const c = await models[n].countDocuments({ farmId: sid(farmId) });
      if (c) counts[n] = c;
      total += c;
    }
    return { total, counts };
  });
}

function mufFarmValueIdentity(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  for (const key of ['_id', 'id', 'key']) {
    if (value[key] !== undefined && value[key] !== null && String(value[key]) !== '') {
      return `${key}:${String(value[key])}`;
    }
  }
  return null;
}

/**
 * Merge the flexible value payloads used by Flock's DataStore buckets.
 * Arrays are unioned by stable row identity when available; object fields are
 * retained from both sides, with source values winning for conflicting scalars.
 */
function mufMergeFarmDataValue(destinationValue, sourceValue) {
  if (Array.isArray(destinationValue) && Array.isArray(sourceValue)) {
    const merged = [...destinationValue];
    for (const incoming of sourceValue) {
      const identity = mufFarmValueIdentity(incoming);
      let index = -1;
      if (identity) {
        index = merged.findIndex((existing) => mufFarmValueIdentity(existing) === identity);
      } else {
        const serialized = JSON.stringify(incoming);
        index = merged.findIndex((existing) => JSON.stringify(existing) === serialized);
      }
      if (index < 0) merged.push(incoming);
      else if (identity) merged[index] = mufMergeFarmDataValue(merged[index], incoming);
    }
    return merged;
  }
  const isPlainObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
  if (isPlainObject(destinationValue) && isPlainObject(sourceValue)) {
    const merged = { ...destinationValue };
    for (const [key, incoming] of Object.entries(sourceValue)) {
      merged[key] = Object.prototype.hasOwnProperty.call(merged, key)
        ? mufMergeFarmDataValue(merged[key], incoming)
        : incoming;
    }
    return merged;
  }
  if (sourceValue === undefined) return destinationValue;
  return sourceValue;
}

/** Move Flock DataStore buckets without violating the unique (farmId, key) index. */
async function mufMoveDataStoreBuckets(DataStore, sourceFarmId, destinationFarmId) {
  const sourceId = sid(sourceFarmId);
  const destinationId = sid(destinationFarmId);
  const sourceBuckets = await DataStore.find({ farmId: sourceId }).lean();

  async function mergeAndRemoveSource(source, destination) {
    const value = mufMergeFarmDataValue(destination.value, source.value);
    const version = Math.max(Number(destination.version) || 0, Number(source.version) || 0) + 1;
    const saved = await DataStore.findOneAndUpdate(
      { _id: destination._id, farmId: destinationId, key: source.key },
      { $set: { value, version } },
      { new: true },
    );
    if (!saved) {
      throw new Error(`DataStore bucket "${source.key}" changed during farm move; source data was retained.`);
    }
    const removed = await DataStore.findOneAndDelete({ _id: source._id, farmId: sourceId });
    if (!removed) {
      throw new Error(`Source DataStore bucket "${source.key}" could not be removed after merge.`);
    }
  }

  for (const source of sourceBuckets) {
    let destination = await DataStore.findOne({ farmId: destinationId, key: source.key }).lean();
    if (destination) {
      await mergeAndRemoveSource(source, destination);
      continue;
    }
    try {
      const moved = await DataStore.findOneAndUpdate(
        { _id: source._id, farmId: sourceId },
        { $set: { farmId: destinationId } },
        { new: true },
      );
      if (moved) continue;
    } catch (error) {
      if (error?.code !== 11000 && error?.codeName !== 'DuplicateKey') throw error;
    }
    destination = await DataStore.findOne({ farmId: destinationId, key: source.key }).lean();
    if (!destination) {
      throw new Error(`DataStore bucket "${source.key}" could not be moved; source data was retained.`);
    }
    await mergeAndRemoveSource(source, destination);
  }
}

/**
 * Router for /api/farms. Pass the express module so this file needs no express import.
 *   list:    owner sees every farm, others only assigned, active ones
 *   create / rename / archive / restore / delete: owner only
 */
export function mufCreateFarmsRouter({ express, Farm, User, models, names, protect, ownerOnly }) {
  const router = express.Router();

  router.get('/', protect, async (req, res) => {
    try {
      const farms = (await Farm.find({}).lean()).sort(byCreated);
      const role = mufNormalizeRole(req.user.role);
      const mine = role === 'owner'
        ? farms
        : farms.filter((f) => !f.archived && (req.user.farmIds || []).map(sid).includes(sid(f._id)));
      const out = [];
      for (const f of mine) {
        const j = farmJson(f);
        if (role === 'owner' && req.query.counts === '1') j.records = (await mufCountFarmRecords(models, names, f._id)).total;
        out.push(j);
      }
      res.json({ farms: out, activeFarmId: req.farmContext?.farmId || null, mode: req.farmContext?.mode || 'single' });
    } catch (e) { res.status(500).json({ error: e.message }); }
  });

  router.post('/', protect, ownerOnly, async (req, res) => {
    try {
      const name = cleanName(req.body?.name);
      if (!name) return res.status(400).json({ error: 'Farm name is required' });
      const dup = (await Farm.find({}).lean()).some((f) => cleanName(f.name).toLowerCase() === name.toLowerCase());
      if (dup) return res.status(409).json({ error: 'A farm with this name already exists' });
      const farm = await Farm.create({ name, location: cleanText(req.body?.location), archived: false, createdBy: req.user.id });
      res.status(201).json(farmJson(farm));
    } catch (e) { res.status(500).json({ error: e.message }); }
  });

  router.put('/:id', protect, ownerOnly, async (req, res) => {
    try {
      const farm = await Farm.findById(req.params.id);
      if (!farm) return res.status(404).json({ error: 'Farm not found' });
      if (req.body?.name !== undefined) {
        const name = cleanName(req.body.name);
        if (!name) return res.status(400).json({ error: 'Farm name is required' });
        const dup = (await Farm.find({}).lean()).some((f) => sid(f._id) !== sid(farm._id) && cleanName(f.name).toLowerCase() === name.toLowerCase());
        if (dup) return res.status(409).json({ error: 'A farm with this name already exists' });
        farm.name = name;
      }
      if (req.body?.location !== undefined) farm.location = cleanText(req.body.location);
      await farm.save();
      res.json(farmJson(farm));
    } catch (e) { res.status(500).json({ error: e.message }); }
  });

  router.post('/:id/archive', protect, ownerOnly, async (req, res) => {
    try {
      const farm = await Farm.findById(req.params.id);
      if (!farm) return res.status(404).json({ error: 'Farm not found' });
      const active = (await Farm.find({}).lean()).filter((f) => !f.archived);
      if (!farm.archived && active.length <= 1) return res.status(400).json({ error: 'You cannot archive the last active farm' });
      farm.archived = true;
      await farm.save();
      res.json(farmJson(farm));
    } catch (e) { res.status(500).json({ error: e.message }); }
  });

  router.post('/:id/restore', protect, ownerOnly, async (req, res) => {
    try {
      const farm = await Farm.findById(req.params.id);
      if (!farm) return res.status(404).json({ error: 'Farm not found' });
      farm.archived = false;
      await farm.save();
      res.json(farmJson(farm));
    } catch (e) { res.status(500).json({ error: e.message }); }
  });

  // Delete rules: an empty farm is deleted directly. A farm with records needs the
  // farm name typed in `confirmName`, and either `moveToFarmId` (move the records)
  // or `deleteData: true` (delete them). The last farm can never be deleted.
  router.delete('/:id', protect, ownerOnly, async (req, res) => {
    try {
      const farm = await Farm.findById(req.params.id);
      if (!farm) return res.status(404).json({ error: 'Farm not found' });
      const all = await Farm.find({}).lean();
      if (all.length <= 1) return res.status(400).json({ error: 'You cannot delete the last farm', code: 'LAST_FARM' });
      const active = all.filter((item) => !item.archived);
      if (!farm.archived && active.length <= 1) {
        return res.status(400).json({ error: 'You cannot delete the last active farm', code: 'LAST_ACTIVE_FARM' });
      }
      const { total } = await mufCountFarmRecords(models, names, farm._id);
      if (total > 0) {
        if (cleanName(req.body?.confirmName) !== cleanName(farm.name)) {
          return res.status(400).json({ error: 'Type the farm name to confirm', code: 'CONFIRM_NAME', records: total });
        }
        const moveTo = sid(req.body?.moveToFarmId);
        if (moveTo) {
          const destination = all.find((item) => sid(item._id) === moveTo);
          if (moveTo === sid(farm._id) || !destination || destination.archived) {
            return res.status(400).json({ error: 'Choose a different active farm to move the records to', code: 'INVALID_MOVE_TARGET' });
          }
          await mufRunUnscoped(async () => {
            for (const n of names) {
              if (n === 'DataStore' && models[n]) {
                await mufMoveDataStoreBuckets(models[n], farm._id, moveTo);
              } else {
                await models[n].updateMany({ farmId: sid(farm._id) }, { $set: { farmId: moveTo } });
              }
            }
          });
        } else if (req.body?.deleteData === true) {
          await mufRunUnscoped(async () => {
            for (const n of names) await models[n].deleteMany({ farmId: sid(farm._id) });
          });
        } else {
          return res.status(400).json({ error: 'Choose moveToFarmId or deleteData', code: 'CHOOSE_DATA_ACTION', records: total });
        }
      }
      await mufRunUnscoped(async () => {
        for (const u of await User.find({}).lean()) {
          const ids = (u.farmIds || []).map(sid);
          if (ids.includes(sid(farm._id))) {
            await User.findByIdAndUpdate(u._id, { $set: { farmIds: ids.filter((x) => x !== sid(farm._id)) } });
          }
        }
        await Farm.findByIdAndDelete(farm._id);
      });
      res.json({ ok: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
  });

  return router;
}

// ─── Migration ──────────────────────────────────────────────────────────────
/**
 * Idempotent. Safe to run twice. Back up first.
 *   1. make sure at least one farm exists ("Farm 1" by default)
 *   2. tag every farm-scoped record that has no farmId with the oldest farm
 *   3. turn legacy admin accounts into owners; give managers and workers with no
 *      farm assigned the oldest farm
 */
export async function mufMigrateFarms({ Farm, User, models, names, farmName = 'Farm 1', log = () => {} }) {
  return mufRunUnscoped(async () => {
    let farms = (await Farm.find({}).lean()).sort(byCreated);
    let created = false;
    if (farms.length === 0) {
      await Farm.create({ name: farmName, location: '', archived: false });
      farms = (await Farm.find({}).lean()).sort(byCreated);
      created = true;
      log(`created farm "${farmName}"`);
    }
    const defaultId = sid(farms[0]._id);
    mufSetDefaultFarmId(defaultId);

    const tagged = {};
    for (const n of names) {
      const r = await models[n].updateMany(
        { $or: [{ farmId: { $exists: false } }, { farmId: null }] },
        { $set: { farmId: defaultId } },
      );
      const count = r?.modifiedCount ?? r?.nModified ?? 0;
      if (count) { tagged[n] = count; log(`tagged ${count} ${n} record(s)`); }
    }

    let rolesConverted = 0;
    let assigned = 0;
    const users = await User.find({}).lean();
    for (const u of users) {
      const patch = {};
      if (u.role === 'admin') { patch.role = 'owner'; rolesConverted += 1; }
      const role = patch.role || u.role;
      if ((role === 'manager' || role === 'worker') && !(u.farmIds || []).length) {
        patch.farmIds = [defaultId];
        assigned += 1;
      }
      if (Object.keys(patch).length) await User.findByIdAndUpdate(u._id, { $set: patch });
    }
    if (rolesConverted) log(`converted ${rolesConverted} admin account(s) to owner`);
    if (assigned) log(`assigned ${assigned} account(s) to the default farm`);
    return { defaultFarmId: defaultId, created, tagged, rolesConverted, assigned };
  });
}

/** Cheap startup check: the default farm id for system jobs. Does not modify data. */
export async function mufLoadDefaultFarm(Farm) {
  return mufRunUnscoped(async () => {
    const farms = (await Farm.find({}).lean()).sort(byCreated);
    mufSetDefaultFarmId(farms[0] ? sid(farms[0]._id) : null);
    return farms[0] ? sid(farms[0]._id) : null;
  });
}

'use strict';
const LIMIT=200;
function photoUrl(value){const s=String(value==null?'':value).trim();if(!s)return '';try{const u=new URL(s);return u.protocol==='https:'?u.href:'';}catch{return '';}}
export const mufPublicProductQuery=()=>({published:true});
export function mufPublicProducts(rows,farms=[]){
 const names=new Map((Array.isArray(farms)?farms:[]).map(f=>[String((f&&(f._id||f.id))||''),String((f&&f.name)||'Farm')]));
 return (Array.isArray(rows)?rows:[]).filter(p=>p&&p.published===true).map(p=>({
  id:String(p._id||p.id||''),farmName:names.get(String(p.farmId||''))||'Farm',name:String(p.name||''),kind:String(p.kind||''),unit:String(p.unit||''),
  price:Number.isFinite(Number(p.price))?Number(p.price):0,quantity:Number.isFinite(Number(p.quantity))?Number(p.quantity):0,photoUrl:photoUrl(p.photoUrl),updatedAt:p.updatedAt||null
 }));
}
export function mufPrivateProduct(p){if(!p)return null;return {
 _id:String(p._id||p.id||''),farmId:String(p.farmId||''),name:String(p.name||''),kind:String(p.kind||''),unit:String(p.unit||''),
 price:Number.isFinite(Number(p.price))?Number(p.price):0,quantity:Number.isFinite(Number(p.quantity))?Number(p.quantity):0,
 photoUrl:photoUrl(p.photoUrl),published:p.published===true,createdAt:p.createdAt||null,updatedAt:p.updatedAt||null
};}
export function mufNormalizeProductInput(input,kinds,options={}){
 const partial=options.partial===true;
 if(!input||typeof input!=='object'||Array.isArray(input))return{ok:false,error:'A product object is required.'};
 const fields={},has=k=>Object.prototype.hasOwnProperty.call(input,k),allowed=Array.isArray(kinds)?kinds:[];
 if(!partial||has('name')){const v=String(input.name==null?'':input.name).trim();if(!v||v.length>120)return{ok:false,error:'Name is required (120 characters max).'};fields.name=v;}
 if(!partial||has('kind')){const v=String(input.kind==null?'':input.kind).trim();if(!allowed.includes(v))return{ok:false,error:'Choose a supported product type.'};fields.kind=v;}
 if(!partial||has('unit')){const v=String(input.unit==null?'':input.unit).trim();if(!v||v.length>32)return{ok:false,error:'Unit is required (32 characters max).'};fields.unit=v;}
 for(const key of ['price','quantity'])if(!partial||has(key)){if(input[key]===''||input[key]==null)return{ok:false,error:'Price and quantity must be non-negative numbers.'};const n=Number(input[key]);if(!Number.isFinite(n)||n<0||n>1000000000)return{ok:false,error:'Price and quantity are out of range.'};fields[key]=n;}
 if(!partial||has('photoUrl')){const v=String(input.photoUrl==null?'':input.photoUrl).trim();if(v.length>500||(v&&!photoUrl(v)))return{ok:false,error:'Photo URL must be HTTPS and 500 characters max.'};fields.photoUrl=v;}
 if(has('published')){if(typeof input.published!=='boolean')return{ok:false,error:'Published must be a boolean.'};fields.published=input.published;}else if(!partial)fields.published=false;
 return{ok:true,fields};
}
export function createMufProductHandlers({Product,Farm,kinds}){
 async function publicList(_req,res){try{
  res.setHeader('Cache-Control','no-store, no-cache, must-revalidate, private');res.setHeader('X-Robots-Tag','noindex, nofollow, noarchive');res.setHeader('Referrer-Policy','no-referrer');
  const rows=await Product.find(mufPublicProductQuery()).sort({updatedAt:-1}).limit(LIMIT).lean();
  const ids=Array.from(new Set((rows||[]).map(p=>String(p.farmId||'')).filter(Boolean)));
  const farms=ids.length?await Farm.find({_id:{$in:ids}}).select('_id name').lean():[];
  res.json({products:mufPublicProducts(rows,farms)});
 }catch{res.status(500).json({error:'Could not load published products.'});}}
 async function list(_req,res){try{const rows=await Product.find({}).sort({updatedAt:-1}).limit(LIMIT).lean();res.json({products:(rows||[]).map(mufPrivateProduct)});}catch{res.status(500).json({error:'Could not load products for this farm.'});}}
 async function create(req,res){const p=mufNormalizeProductInput(req.body,kinds);if(!p.ok)return res.status(400).json({error:p.error});try{const product=await Product.create(p.fields);return res.status(201).json({product:mufPrivateProduct(product)});}catch{return res.status(400).json({error:'Could not save product. Check its values.'});}}
 async function update(req,res){const p=mufNormalizeProductInput(req.body,kinds,{partial:true});if(!p.ok)return res.status(400).json({error:p.error});if(!Object.keys(p.fields).length)return res.status(400).json({error:'No supported fields supplied.'});try{const product=await Product.findOneAndUpdate({_id:req.params.id},{$set:p.fields},{new:true,runValidators:true});if(!product)return res.status(404).json({error:'Product not found in selected farm.'});return res.json({product:mufPrivateProduct(product)});}catch{return res.status(400).json({error:'Could not update product. Check its values.'});}}
 async function remove(req,res){try{const p=await Product.findOneAndDelete({_id:req.params.id});if(!p)return res.status(404).json({error:'Product not found in selected farm.'});return res.json({ok:true});}catch{return res.status(500).json({error:'Could not delete product.'});}}
 return{publicList,list,create,update,remove};
}

// muf-query.mjs — shared in-memory query/match/update engine used by the
// memory-db.js of all three farm backends (dairy / flock / agri).
//
// One file, three byte-identical copies (backend/muf-query.mjs in each app).
// Each app's memory-db.js keeps its own model/document API on top and passes
// its dialect options:
//   - { loose: true }   flock (string-tolerant equality)
//   - { nullsLast }     flock (missing values sort last)

import crypto from 'crypto';

// 24-hex id that passes MongoDB ObjectId validation
export function mufNewId() {
  return crypto.randomBytes(12).toString('hex');
}

export function mufClone(v) {
  if (Array.isArray(v)) return v.map(mufClone);
  if (v && typeof v === 'object' && v instanceof Date) return new Date(v.getTime());
  if (v && typeof v === 'object') {
    const out = {};
    for (const k of Object.keys(v)) out[k] = mufClone(v[k]);
    return out;
  }
  return v;
}

export function mufGetPath(obj, path) {
  if (obj == null) return undefined;
  if (!path.includes('.')) return obj[path];
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
}

export function mufSetPath(obj, path, value) {
  const keys = path.split('.');
  let cur = obj;
  for (let i = 0; i < keys.length - 1; i++) {
    if (cur[keys[i]] == null || typeof cur[keys[i]] !== 'object') cur[keys[i]] = {};
    cur = cur[keys[i]];
  }
  cur[keys[keys.length - 1]] = value;
}

// Loose equality (flock dialect): numbers and strings compare by String()
export function mufEq(a, b) {
  if (a === b) return true;
  if (a instanceof Date || b instanceof Date) {
    const ta = a instanceof Date ? a.getTime() : new Date(a).getTime();
    const tb = b instanceof Date ? b.getTime() : new Date(b).getTime();
    return ta === tb;
  }
  if (b === null) return a == null;
  if (a == null || b == null) return false;
  return String(a) === String(b);
}

function toComparable(v) {
  if (v instanceof Date) return v.getTime();
  return v;
}

// Sort compare: Dates by timestamp, nulls/undefined count as smallest
export function mufCompare(a, b) {
  a = toComparable(a);
  b = toComparable(b);
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

export function mufIsOperatorObject(cond) {
  return cond !== null && typeof cond === 'object' && !Array.isArray(cond)
    && !(cond instanceof Date) && Object.keys(cond).length > 0
    && Object.keys(cond).every((k) => k.startsWith('$'));
}

export function mufMatchValue(docVal, cond, { loose = false } = {}) {
  if (mufIsOperatorObject(cond)) {
    return Object.entries(cond).every(([op, v]) => {
      switch (op) {
        case '$ne': return loose ? !mufEq(docVal, v) : !(docVal === v);
        case '$gt': return docVal != null && mufCompare(docVal, v) > 0;
        case '$gte': return docVal != null && mufCompare(docVal, v) >= 0;
        case '$lt': return docVal != null && mufCompare(docVal, v) < 0;
        case '$lte': return docVal != null && mufCompare(docVal, v) <= 0;
        case '$exists': return Boolean(v) === (docVal !== undefined && docVal !== null);
        case '$in': return Array.isArray(v) && v.some((x) => (loose ? mufEq(docVal, x) : docVal === x));
        case '$nin': return !(Array.isArray(v) && v.some((x) => (loose ? mufEq(docVal, x) : docVal === x)));
        case '$regex':
          try { return new RegExp(v, String(cond.$options || '')).test(String(docVal ?? '')); } catch { return false; }
        case '$options': return true;
        case '$type': return true; // not needed in memory mode
        default: return true;
      }
    });
  }
  return loose ? mufEq(docVal, cond) : docVal === cond;
}

export function mufMatches(doc, filter = {}, opts = {}) {
  if (!filter) return true;
  return Object.entries(filter).every(([key, cond]) => {
    if (key === '$or') return Array.isArray(cond) && cond.some((sub) => mufMatches(doc, sub, opts));
    if (key === '$and') return Array.isArray(cond) && cond.every((sub) => mufMatches(doc, sub, opts));
    return mufMatchValue(mufGetPath(doc, key), cond, opts);
  });
}

export function mufSort(rows, sortSpec, { nullsLast = false } = {}) {
  if (!sortSpec) return rows;
  const entries = Array.isArray(sortSpec) ? sortSpec : Object.entries(sortSpec);
  const sorted = rows.slice();
  sorted.sort((a, b) => {
    for (const [field, dir] of entries) {
      const av = mufGetPath(a, field);
      const bv = mufGetPath(b, field);
      if (nullsLast) {
        const an = av === undefined || av === null;
        const bn = bv === undefined || bv === null;
        if (an || bn) {
          if (an && bn) continue;
          return an ? 1 : -1;
        }
      }
      const c = mufCompare(av, bv);
      if (c !== 0) return dir < 0 ? -c : c;
    }
    return 0;
  });
  return sorted;
}

export function mufPullMatch(item, cond) {
  if (!mufIsOperatorObject(cond)) return item === cond;
  return Object.entries(cond).every(([k, v]) => mufGetPath(item, k) === v);
}

export function mufApplyUpdate(doc, update) {
  const hasOperator = Object.keys(update).some((k) => k.startsWith('$'));
  if (!hasOperator) {
    // Bare object == $set
    for (const [k, v] of Object.entries(update)) mufSetPath(doc, k, v);
    return;
  }
  if (update.$set) {
    for (const [k, v] of Object.entries(update.$set)) mufSetPath(doc, k, v);
  }
  if (update.$push) {
    for (const [k, v] of Object.entries(update.$push)) {
      if (!Array.isArray(doc[k])) doc[k] = [];
      doc[k].push(v);
    }
  }
  if (update.$pull) {
    for (const [k, v] of Object.entries(update.$pull)) {
      if (!Array.isArray(doc[k])) continue;
      doc[k] = doc[k].filter((item) => !mufPullMatch(item, v));
    }
  }
  if (update.$inc) {
    for (const [k, v] of Object.entries(update.$inc)) doc[k] = (Number(doc[k]) || 0) + v;
  }
  if (update.$unset) {
    for (const k of Object.keys(update.$unset)) delete doc[k];
  }
}

export function mufProject(doc, selectSpec) {
  let fields;
  if (typeof selectSpec === 'string') {
    fields = selectSpec.split(/\s+/).filter(Boolean);
  } else if (Array.isArray(selectSpec)) {
    fields = selectSpec;
  } else if (selectSpec && typeof selectSpec === 'object') {
    fields = Object.keys(selectSpec).filter((k) => selectSpec[k]);
  } else {
    return doc;
  }
  const out = {};
  if (!fields.includes('-_id')) out._id = doc._id;
  for (const f of fields) {
    if (f.startsWith('-')) continue;
    out[f] = mufGetPath(doc, f);
  }
  return out;
}

/* ─────────────────────────────────────────────────────────────
 * muf-telegram — shared Telegram-bot brain (muf twin file).
 * Parses worker messages ("doodh bella 12", "anday 320",
 * "kharcha 500 chara", "hazri", "hisab") in English + Urdu and
 * carries the shared reply texts + Telegram API helpers.
 * ESM on purpose: flock imports it directly; dairy (CommonJS)
 * loads it with `await import()`. Keep identical in dairy_farm
 * & flock_farm backends; agri carries the same logic as
 * backend/muf_telegram.py. Run `node check-muf-sync.js`.
 * ──────────────────────────────────────────────────────────── */

/** Urdu / English keyword → intent. */
const KEYWORDS = {
  milk: ['milk', 'doodh', 'dodh', 'دودھ'],
  eggs: ['eggs', 'egg', 'anday', 'anda', 'انڈے', 'انڈا', 'انڈہ'],
  expense: ['expense', 'kharcha', 'kharch', 'خرچہ', 'خرچا', 'خرچ'],
  attendance: ['hazri', 'haazri', 'attendance', 'حاضری'],
  summary: ['hisab', 'hisaab', 'summary', 'حساب', 'khulasa', 'خلاصہ'],
  help: ['help', 'madad', 'مدد', 'start'],
};

function keywordKind(word) {
  const w = String(word || '').toLowerCase().replace(/[.,!؟?]/g, '');
  for (const [kind, list] of Object.entries(KEYWORDS)) {
    if (list.includes(w)) return kind;
  }
  return null;
}

/** Convert Urdu/Arabic-Indic digits to Latin so "۴۵" parses as 45. */
export function normalizeDigits(text) {
  return String(text || '')
    .replace(/[۰-۹]/g, (d) => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))
    .replace(/[٠-٩]/g, (d) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
}

/**
 * Parse one incoming message into a command.
 * Returns { kind, code?, qty?, name?, words? }.
 *   kind: 'link' | 'milk' | 'eggs' | 'expense' | 'attendance'
 *       | 'summary' | 'help' | 'unknown'
 */
export function parseCommand(rawText) {
  const text = normalizeDigits(String(rawText || '').trim());
  if (!text) return { kind: 'unknown' };

  // /start 123456 → link request; bare /start → help
  const start = text.match(/^\/start(?:\s+(\d{4,8}))?\s*$/i);
  if (start) return start[1] ? { kind: 'link', code: start[1] } : { kind: 'help' };
  const slash = text.match(/^\/(help|hisab|summary|hazri)\s*$/i);
  if (slash) return { kind: keywordKind(slash[1]) || 'help' };

  const tokens = text.split(/\s+/);
  const kind = keywordKind(tokens[0]);
  if (!kind) return { kind: 'unknown' };
  if (kind === 'help' || kind === 'summary' || kind === 'attendance') return { kind };

  // qty = first number in the rest; name/words = remaining tokens
  const rest = tokens.slice(1);
  let qty = null;
  const words = [];
  for (const t of rest) {
    const n = parseFloat(t.replace(/,/g, ''));
    if (qty === null && Number.isFinite(n) && /^[\d.,]+$/.test(t)) qty = n;
    else words.push(t);
  }
  return { kind, qty, name: words.join(' ').trim(), words };
}

/** Map free-text expense words to a coarse category hint. */
export function expenseHint(words) {
  const w = (Array.isArray(words) ? words.join(' ') : String(words || '')).toLowerCase();
  if (/chara|charah|feed|khal|wanda|چارہ|ونڈا|کھل/.test(w)) return 'feed';
  if (/dawai|dawa|medicine|vaccine|دوائی|دوا|ویکسین/.test(w)) return 'medicine';
  if (/mazdoor|labor|labour|مزدور|اجرت/.test(w)) return 'labor';
  return 'misc';
}

