router.delete('/batches/:batchId', authRequired, requireRole('admin'), async (req, res) => {
  let releaseInventoryLock;
  try {
    releaseInventoryLock = await acquireEggInventoryLock(DataStore);
    const batch = await getBatchByCode(req.params.batchId);
    if (!batch) return res.status(404).json({ error: 'Batch not found' });

    const [incubation, laborAttendance] = await Promise.all([
      DataStore.findOne({ key: 'incubation' }),
      DataStore.findOne({ key: 'laborAttendance' }),
    ]);
    const linkedIncubation = Array.isArray(incubation?.value)
      ? incubation.value.filter((record) => String(record?.sourceBatchId || '') === batch.batch_id)
      : [];
    const linkedAttendance = Array.isArray(laborAttendance?.value)
      ? laborAttendance.value.filter((record) => String(record?.batchId || '') === batch.batch_id)
      : [];
    if (linkedIncubation.length || linkedAttendance.length) {
      return res.status(409).json({
        error: 'This batch is linked to incubation or labor history. Reassign or unlink those records before deleting the batch.',
        code: 'BATCH_HAS_LINKED_HISTORY',
        linkedIncubationRecords: linkedIncubation.length,
        linkedLaborRecords: linkedAttendance.length,
      });
    }

    // Free the batch photos' DB space along with the batch itself
    if (batch.image_path) await deleteImageByPath(batch.image_path, req.farmContext?.farmId);
    for (const path of batch.gallery || []) await deleteImageByPath(path, req.farmContext?.farmId);

    await Promise.all([
      BatchFeedLog.deleteMany({ batch_id: batch.batch_id }),
      BatchMortalityLog.deleteMany({ batch_id: batch.batch_id }),
      BatchExpenseLog.deleteMany({ batch_id: batch.batch_id }),
      BatchSaleLog.deleteMany({ batch_id: batch.batch_id }),
      BatchWeightLog.deleteMany({ batch_id: batch.batch_id }),
      BatchEggLog.deleteMany({ batch_id: batch.batch_id }),
      BatchVaccinationLog.deleteMany({ batch_id: batch.batch_id }),
      batch.deleteOne(),
    ]);

    res.json({ ok: true });
  } catch (err) {
    if (err?.code === 'EGG_INVENTORY_BUSY') return res.status(409).json({ error: err.message, code: err.code, retryable: true });
    console.error('DELETE /api/batches/:batchId error:', err);
    res.status(500).json({ error: 'Failed to delete batch' });
  } finally {
    if (releaseInventoryLock) { try { await releaseInventoryLock(); } catch (e) { console.error('Failed to release egg inventory lock:', e); } }
  }
});

// ─── Batch photo gallery ────────────────────────────────────────────────────
// Extra dated photos per batch. Upload the image first via POST /api/upload
// (kind 'batch'), then attach the returned path here. Max 10 photos.

router.post('/batches/:batchId/gallery', authRequired, async (req, res) => {
  try {
    const batch = await getBatchByCode(req.params.batchId);
    if (!batch) return res.status(404).json({ error: 'Batch not found' });
    const imagePath = String(req.body?.image_path || '').trim();
    const imageId = imagePath.match(/^\/api\/images\/([a-f0-9]{24})$/i)?.[1];
    const farmId = String(req.farmContext?.farmId || '');
    if (!imageId || !farmId) {
      return res.status(400).json({ error: 'image_path must be an uploaded /api/images/<id> path in the selected farm' });
    }
    const image = await Image.findOne({ _id: imageId, farmId, kind: 'batch' }).select('_id').lean();
    if (!image) return res.status(400).json({ error: 'Batch photo must belong to the selected farm' });
    const gallery = Array.isArray(batch.gallery) ? batch.gallery : [];
    if (gallery.length >= 10) return res.status(400).json({ error: 'Gallery is limited to 10 photos' });
    if (!gallery.includes(imagePath)) {
      batch.gallery = [...gallery, imagePath];
      await batch.save();
    }
    res.status(201).json({ gallery: batch.gallery });
  } catch (err) {
    console.error('POST batch gallery error:', err);
    res.status(500).json({ error: 'Failed to add gallery photo' });
  }
});

router.delete('/batches/:batchId/gallery', authRequired, requireRole('admin'), async (req, res) => {
  try {
    const batch = await getBatchByCode(req.params.batchId);
    if (!batch) return res.status(404).json({ error: 'Batch not found' });
    const imagePath = String(req.query?.path || '').trim();
    if (!imagePath || !(batch.gallery || []).includes(imagePath)) {
      return res.status(404).json({ error: 'Photo not found in this batch gallery' });
    }
    batch.gallery = (batch.gallery || []).filter((g) => g !== imagePath);
    await batch.save();
    await deleteImageByPath(imagePath, req.farmContext?.farmId);
    res.json({ gallery: batch.gallery });
  } catch (err) {
    console.error('DELETE batch gallery error:', err);
    res.status(500).json({ error: 'Failed to remove gallery photo' });
  }
});

router.delete('/batches/logs/:kind/:logId', authRequired, requireRole('admin'), async (req, res) => {
  let releaseInventoryLock;
  try {
    const models = {
      feed: BatchFeedLog,
      mortality: BatchMortalityLog,
      expense: BatchExpenseLog,
      sale: BatchSaleLog,
      weight: BatchWeightLog,
      egg: BatchEggLog,
      vaccination: BatchVaccinationLog,
    };
    const Model = models[req.params.kind];
    if (!Model) return res.status(400).json({ error: 'Unknown log type' });

    if (req.params.kind === 'egg') releaseInventoryLock = await acquireEggInventoryLock(DataStore);
    const log = await Model.findById(req.params.logId);
    if (!log) return res.status(404).json({ error: 'Log not found' });

    if (req.params.kind === 'egg') {
      const incubation = await DataStore.findOne({ key: 'incubation' });
      const records = Array.isArray(incubation?.value) ? incubation.value : [];
      const linkedBatchIds = [...new Set(
        records.map((record) => String(record?.sourceBatchId || '').trim()).filter(Boolean),
      )];
      const [batches, eggLogs] = linkedBatchIds.length
        ? await Promise.all([
          Batch.find({ batch_id: { $in: linkedBatchIds } }),
          BatchEggLog.find({ batch_id: { $in: linkedBatchIds } }),
        ])
        : [[], []];
      const remainingLogs = eggLogs.filter((item) => String(item._id) !== String(log._id));
      const allocationError = validateIncubationAllocations(records, batches, remainingLogs);
      if (allocationError) {
        return res.status(409).json({
          error: `Cannot delete this egg log because it would invalidate an incubation allocation. ${allocationError}`,
          code: 'EGG_LOG_HAS_INCUBATION_ALLOCATIONS',
        });
      }
    }

    await Model.findByIdAndDelete(req.params.logId);
    const batch = await getBatchByCode(log.batch_id);
    if (batch) await syncBatchStatus(batch);
    res.json({ ok: true });
  } catch (err) {
    if (err?.code === 'EGG_INVENTORY_BUSY') return res.status(409).json({ error: err.message, code: err.code, retryable: true });
    console.error('DELETE batch log error:', err);
    res.status(500).json({ error: 'Failed to delete batch log' });
  } finally {
    if (releaseInventoryLock) { try { await releaseInventoryLock(); } catch (e) { console.error('Failed to release egg inventory lock:', e); } }
  }
});

export default router;

// Flock Farm — generic key/value data store endpoints + worker-write validation.
//
// Extracted from server.js so server.js stays focused on middleware + mounting
// (same pattern dairy_farm and agri_farm already follow). All flock-specific
// worker-permission logic (which fields a worker may/may not touch on a bird,
// the "workers cannot mark birds as sold" rule, etc.) lives here and only here.
//
// Routes mounted at /api by server.js, so the public paths stay:
//   GET  /api/data/:key   — read any bucket (admin or worker)
//   PUT  /api/data/:key   — write a bucket (role-gated, optimistic-concurrency)
import express from 'express';
import mongoose from 'mongoose';
import DataStore from '../models/DataStore.js';
import Image from '../models/Image.js';
import { extractImageIds, findUnreferencedImageIds } from '../image-references.mjs';
import Batch from '../models/Batch.js';
import BatchEggLog from '../models/BatchEggLog.js';
import { validateIncubationAllocations } from '../incubation-allocation.mjs';
import { validateLaborBatchAssignments } from '../batch-labor.mjs';
import { acquireEggInventoryLock } from '../egg-inventory-lock.mjs';
import { authRequired } from '../middleware/auth.js';
import { MUF_ENV } from '../muf-env.mjs';
import { createCloudinaryClient, cloudinaryConfigured } from '../muf-cloudinary.mjs';

const router = express.Router();

// ─── Bucket whitelist + per-role write rules ────────────────────────────────
const ALLOWED_KEYS = [
  'birds', 'expenses', 'feed', 'eggs', 'settings',
  'vaccinations', 'customers', 'customerSales',
  'incubation', 'checklist', 'diary',
  'laborers', 'laborAttendance', 'laborAdvances',
  'suppliers', 'supplierPayments',
];

const ADMIN_ONLY_WRITE_KEYS = new Set([
  'birds', 'settings', 'customers',
  'laborers', 'laborAttendance', 'laborAdvances',
  'suppliers', 'supplierPayments',
]);

const WORKER_WRITE_KEYS = new Set([
  'expenses', 'feed', 'eggs', 'vaccinations',
  'customerSales', 'incubation', 'checklist', 'diary',
]);

// Workers may edit only these fields on a bird record. Everything else is
// immutable from a worker session — protects identity, sale price, photo, etc.
const WORKER_MUTABLE_BIRD_FIELDS = new Set([
  'status',
  'lastVaccinationDate',
  'dateDied',
  'deathReason',
  'deathDetail',
]);

const IMMUTABLE_BIRD_FIELDS_FOR_WORKERS = [
  'id',
  'name',
  'gender',
  'dateBought',
  'price',
  'ageBoughtDays',
  'breed',
  'customBreed',
  'image',
  'dateOfBirth',
  'salePrice',
  'saleDate',
];

// ─── Helpers ────────────────────────────────────────────────────────────────
function sameValue(a, b) {
  return JSON.stringify(a ?? null) === JSON.stringify(b ?? null);
}

function validateWorkerBirdWrite(existingBirds, incomingBirds) {
  if (!Array.isArray(existingBirds) || !Array.isArray(incomingBirds)) {
    return { ok: false, error: 'Bird data must stay an array.' };
  }
  if (existingBirds.length !== incomingBirds.length) {
    return { ok: false, error: 'Workers cannot add or delete birds.' };
  }

  const existingById = new Map(existingBirds.map((bird) => [bird.id, bird]));
  for (const bird of incomingBirds) {
    const previous = existingById.get(bird.id);
    if (!previous) {
      return { ok: false, error: 'Workers cannot create new bird records.' };
    }

    for (const field of IMMUTABLE_BIRD_FIELDS_FOR_WORKERS) {
      if (!sameValue(previous[field], bird[field])) {
        return { ok: false, error: `Workers cannot modify bird field "${field}".` };
      }
    }

    for (const key of Object.keys(bird)) {
      if (!WORKER_MUTABLE_BIRD_FIELDS.has(key) && !IMMUTABLE_BIRD_FIELDS_FOR_WORKERS.includes(key)) {
        if (!sameValue(previous[key], bird[key])) {
          return { ok: false, error: `Workers cannot modify bird field "${key}".` };
        }
      }
    }

    if (bird.status === 'Sold' && previous.status !== 'Sold') {
      return { ok: false, error: 'Workers cannot mark birds as sold.' };
    }
  }

  return { ok: true };
}

// ─── Image space GC ─────────────────────────────────────────────────────────
// Photos may be shared by a bird and a diary entry. Before deleting a candidate,
// inspect every current bucket in the active farm, not only the bucket just saved.
async function cleanupOrphanedImages(candidateIds, farmId) {
  try {
    const scopedFarmId = String(farmId || '');
    if (!scopedFarmId || !candidateIds?.size) return;
    const buckets = await DataStore.find({}).select('value').lean();
    const unreferenced = findUnreferencedImageIds(candidateIds, buckets.map((bucket) => bucket.value));
    let deleted = 0;
    let skippedCloudinary = 0;
    const config = { cloudName: MUF_ENV.cloudinaryCloudName, apiKey: MUF_ENV.cloudinaryApiKey, apiSecret: MUF_ENV.cloudinaryApiSecret };
    const cloudinary = cloudinaryConfigured(config) ? createCloudinaryClient(config) : null;
    for (const id of unreferenced) {
      if (!mongoose.isValidObjectId(id)) continue;
      // Image has no automatic farm-scope plugin: enforce ownership explicitly.
      const image = await Image.findOne({ _id: id, farmId: scopedFarmId });
      if (!image) continue;
      if (image.provider === 'cloudinary' && image.cloudinaryPublicId) {
        if (!cloudinary) { skippedCloudinary++; continue; }
        await cloudinary.destroy(image.cloudinaryPublicId);
      }
      const result = await Image.deleteOne({ _id: id, farmId: scopedFarmId });
      deleted += result.deletedCount || 0;
    }
    if (deleted > 0) console.log(`🗑️  Freed ${deleted} orphaned farm image(s) from storage.`);
    if (skippedCloudinary > 0) console.warn(`[photo-storage] Kept ${skippedCloudinary} Cloudinary orphan record(s) because credentials are missing.`);
  } catch (err) {
    console.error('Image cleanup failed (non-fatal):', err.message);
  }
}

// ─── GET /data/:key ─────────────────────────────────────────────────────────
// Any logged-in user (admin or worker) can read data.
// Returns `version` so clients can do optimistic-concurrency writes.
router.get('/data/:key', authRequired, async (req, res) => {
  const { key } = req.params;
  if (!ALLOWED_KEYS.includes(key)) {
    return res.status(400).json({ error: `Unknown data key: ${key}` });
  }
  try {
    const doc = await DataStore.findOne({ key });
    res.json({
      key,
      exists: !!doc,
      value: doc ? doc.value : null,
      version: doc ? (doc.version || 0) : 0,
    });
  } catch (err) {
    console.error('GET /api/data error:', err);
    res.status(500).json({ error: 'Failed to load data' });
  }
});

// ─── PUT /data/:key ─────────────────────────────────────────────────────────
// Authenticated write with SERVER-SIDE role enforcement. Workers may log
// day-to-day activity only; structural data remains admin-only even if someone
// bypasses the UI and calls the API directly.
//
// Concurrency: clients send `baseVersion` (the version they loaded). If the
// stored version differs, another user saved in between — reject with 409 and
// return the fresh data so the client can merge/reload instead of silently
// overwriting (last-write-wins data loss). The final write is CONDITIONAL on
// the version still matching, which also closes the worker-validation
// read-then-write race (TOCTOU).
router.put('/data/:key', authRequired, async (req, res) => {
  const { key } = req.params;
  if (!ALLOWED_KEYS.includes(key)) {
    return res.status(400).json({ error: `Unknown data key: ${key}` });
  }
  let releaseInventoryLock;
  try {
    const { value, baseVersion } = req.body;

    // Role gate first (cheap, no DB read needed for the non-birds cases)
    if (req.user.farmRole === 'worker' || (!req.user.farmRole && req.user.role !== 'admin')) {
      if (key !== 'birds') {
        if (!WORKER_WRITE_KEYS.has(key)) {
          return res.status(403).json({ error: `Workers cannot modify "${key}"` });
        }
        if (ADMIN_ONLY_WRITE_KEYS.has(key)) {
          return res.status(403).json({ error: `Admin role required to modify "${key}"` });
        }
      }
    }

    // Serialize linked-history writes with batch deletion/replacement and serialize
    // incubation allocations with egg-supply mutations. The shared lock is farm-scoped.
    if (key === 'incubation' || key === 'laborAttendance') {
      releaseInventoryLock = await acquireEggInventoryLock(DataStore);
    }

    const current = await DataStore.findOne({ key });
    const currentVersion = current ? (current.version || 0) : 0;
    // Snapshot image references BEFORE the write — needed for image garbage collection
    // below (in-memory mode returns live objects, so reading after the
    // update would already show the new value).
    const oldImageIds = (key === 'birds' || key === 'diary') ? extractImageIds(current ? current.value : null) : null;

    // Optimistic-concurrency check (only when the client opts in by sending
    // baseVersion — keeps backwards compatibility with older clients).
    if (baseVersion !== undefined && baseVersion !== null) {
      const base = Number(baseVersion);
      if (!Number.isFinite(base) || base !== currentVersion) {
        return res.status(409).json({
          error: 'This data was changed by another user since you loaded it. Refresh to get the latest version.',
          conflict: true,
          key,
          value: current ? current.value : null,
          version: currentVersion,
        });
      }
    }

    // Worker bird-write validation against the same snapshot we version-check
    if ((req.user.farmRole === 'worker' || (!req.user.farmRole && req.user.role !== 'admin')) && key === 'birds') {
      const validation = validateWorkerBirdWrite(current?.value ?? [], value);
      if (!validation.ok) {
        return res.status(403).json({ error: validation.error });
      }
    }

    // Labor attendance may be linked to a batch, but the server must reject
    // batch IDs outside the selected farm even if the client bypasses the UI.
    if (key === 'laborAttendance') {
      const linkedBatchIds = Array.isArray(value)
        ? [...new Set(value.map((record) => String(record?.batchId || '').trim()).filter(Boolean))]
        : [];
      const batches = linkedBatchIds.length
        ? await Batch.find({ batch_id: { $in: linkedBatchIds } })
        : [];
      const assignmentError = validateLaborBatchAssignments(value, batches);
      if (assignmentError) return res.status(400).json({ error: assignmentError, code: 'LABOR_BATCH_ASSIGNMENT' });
    }

    // Incubation source-batch links are a real allocation, not just display metadata.
    // Queries inherit the active farm context from auth middleware. The datastore
    // version compare below prevents two clients saving against the same old bucket.
    if (key === 'incubation') {
      const linkedBatchIds = Array.isArray(value)
        ? [...new Set(value.map((record) => String(record?.sourceBatchId || '').trim()).filter(Boolean))]
        : [];
      const [batches, eggLogs] = linkedBatchIds.length
        ? await Promise.all([
          Batch.find({ batch_id: { $in: linkedBatchIds } }),
          BatchEggLog.find({ batch_id: { $in: linkedBatchIds } }),
        ])
        : [[], []];
      const allocationError = validateIncubationAllocations(value, batches, eggLogs);
      if (allocationError) return res.status(400).json({ error: allocationError, code: 'INCUBATION_EGG_ALLOCATION' });
    }

    // Conditional write: only succeeds if version is still what we read.
    // Legacy docs (created before versioning) have no `version` field at all,
    // and `{version: 0}` does NOT match a missing field in MongoDB — so when
    // the expected version is 0, also accept docs where the field is absent.
    let doc;
    if (current) {
      const versionMatch = currentVersion === 0
        ? { $or: [{ version: 0 }, { version: null }, { version: { $exists: false } }] }
        : { version: currentVersion };
      doc = await DataStore.findOneAndUpdate(
        { key, ...versionMatch },
        { $set: { value, version: currentVersion + 1 } },
        { new: true }
      );
    } else {
      try {
        doc = await DataStore.create({ key, value, version: 1 });
      } catch (createErr) {
        // Duplicate key: someone else created the doc concurrently
        if (createErr && createErr.code === 11000) doc = null;
        else throw createErr;
      }
    }

    if (!doc) {
      const fresh = await DataStore.findOne({ key });
      return res.status(409).json({
        error: 'This data was changed by another user while saving. Refresh to get the latest version.',
        conflict: true,
        key,
        value: fresh ? fresh.value : null,
        version: fresh ? (fresh.version || 0) : 0,
      });
    }

    // Free storage: delete Image docs no longer referenced by any bird
    if ((key === 'birds' || key === 'diary') && oldImageIds) {
      const newImageIds = extractImageIds(doc.value);
      const candidates = new Set([...oldImageIds].filter((id) => !newImageIds.has(id)));
      await cleanupOrphanedImages(candidates, req.farmContext?.farmId);
    }

    res.json({ key, exists: true, value: doc.value, version: doc.version || 0 });
  } catch (err) {
    if (err?.code === 'EGG_INVENTORY_BUSY') {
      return res.status(409).json({ error: err.message, code: err.code, retryable: true });
    }
    console.error('PUT /api/data error:', err);
    res.status(500).json({ error: 'Failed to save data' });
  } finally {
    if (releaseInventoryLock) {
      try { await releaseInventoryLock(); }
      catch (releaseError) { console.error('Failed to release egg inventory lock:', releaseError); }
    }
  }
});

export default router;

// ─── Telegram bot for Usman Flock Farm ───────────────────────────
// Workers send simple messages ("anday 320", "kharcha 500 chara",
// "hazri", "hisab") and the bot writes into the SAME data buckets the
// app writes. Command parsing + reply texts live in the shared
// muf-telegram twin (../muf-telegram.mjs). Webhook-based (autoscale-safe).
//
// Secrets: TELEGRAM_BOT_TOKEN (from @BotFather), TELEGRAM_WEBHOOK_SECRET
// (any long random string). Both unset → telegram stays silently off.
import express from 'express';
import { timingSafeEqual } from 'crypto';
import { authRequired, requireRole } from '../middleware/auth.js';
import DataStore from '../models/DataStore.js';
import Farm from '../models/Farm.js';
import { mufGetDefaultFarmId, mufGetFarmContext, mufRunWithFarmContext, mufIsOwner } from '../muf-farms.mjs';
import { mufTelegramFarmId, mufRunTelegramFarm } from '../muf-telegram-farms.mjs';
import User from '../models/User.js';
import { buildDailySummary } from '../utils/summary.js';
import {
  parseCommand, expenseHint, TG,
  tgSendMessage, tgSetWebhook, tgGetBotUsername, tgNewLinkCode,
  mufDropCheck, tgDropAlert,
} from '../muf-telegram.mjs';

const router = express.Router();

const TOKEN = () => MUF_ENV.telegramBotToken || '';
const WH_SECRET = () => MUF_ENV.telegramWebhookSecret || '';

const LINKS_KEY = 'telegram_links';
const CODES_KEY = 'telegram_codes';

// Farm-local "today"/days-ago helpers come from the shared muf-date twin
// (../muf-date.mjs, byte-identical in all three backends — Pakistan +5).
import { mufToday, mufDaysAgo } from '../muf-date.mjs';
import { MUF_ENV } from '../muf-env.mjs';

const todayLocal = mufToday;
const daysAgoLocal = mufDaysAgo;

async function readStore(key, fallback) {
  const filter = { key };
  if (!mufGetFarmContext() && mufGetDefaultFarmId()) filter.farmId = mufGetDefaultFarmId();
  const doc = await DataStore.findOne(filter);
  return doc?.value ?? fallback;
}
// Version-bumped write — same contract the app's PUT /api/data uses,
// so optimistic-concurrency clients see a fresh version after bot writes.
async function writeStore(key, value) {
  const filter = { key };
  if (!mufGetFarmContext() && mufGetDefaultFarmId()) filter.farmId = mufGetDefaultFarmId();
  const current = await DataStore.findOne(filter);
  const version = (current?.version || 0) + 1;
  await DataStore.findOneAndUpdate(filter, { $set: { key, value, version } }, { upsert: true, new: true });
}

// ── Admin: status ──
router.get('/status', authRequired, requireRole('admin'), async (_req, res) => {
  try {
    const links = await readStore(LINKS_KEY, {});
    const botUsername = TOKEN() ? await tgGetBotUsername(TOKEN()) : null;
    res.json({
      configured: !!(TOKEN() && WH_SECRET()),
      botUsername,
      links: Object.entries(links).map(([chatId, v]) => ({ chatId, ...v })),
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Admin: create link code ──
router.post('/link-code', authRequired, requireRole('admin'), async (req, res) => {
  try {
    const { userId, laborerId } = req.body || {};
    const farmId = mufGetFarmContext()?.farmId;
    if (!farmId) return res.status(400).json({ error: 'Select one farm before creating a Telegram link code' });
    let username = '';
    let laborerName = '';
    if (userId) {
      const u = await User.findById(userId);
      if (!u) return res.status(404).json({ error: 'User not found' });
      const assignedFarmIds = (u.farmIds || []).map(String);
      if (!mufIsOwner(u.role) && !assignedFarmIds.includes(String(farmId))) {
        return res.status(404).json({ error: 'User not found in the selected farm' });
      }
      username = u.username;
    }
    if (laborerId) {
      const laborers = await readStore('laborers', []);
      const lw = laborers.find((l) => String(l.id) === String(laborerId));
      if (!lw) return res.status(404).json({ error: 'Worker not found' });
      laborerName = lw.name;
    }
    if (!userId && !laborerId) return res.status(400).json({ error: 'Pick an app user or a wage worker to link' });
    const codes = await readStore(CODES_KEY, {});
    const now = Date.now();
    for (const [c, v] of Object.entries(codes)) if ((v.expires || 0) < now) delete codes[c];
    const code = tgNewLinkCode();
    codes[code] = { userId: userId || '', username, laborerId: laborerId || '', laborerName, farmId: String(farmId), expires: now + 15 * 60 * 1000 };
    await writeStore(CODES_KEY, codes);
    res.json({ code, expiresInMinutes: 15 });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Admin: unlink ──
router.delete('/links/:chatId', authRequired, requireRole('admin'), async (req, res) => {
  try {
    const links = await readStore(LINKS_KEY, {});
    delete links[req.params.chatId];
    await writeStore(LINKS_KEY, links);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Webhook ──
router.post('/webhook/:secret', async (req, res) => {
  res.json({ ok: true }); // always 200 fast — no Telegram retry loops
  try {
    if (!WH_SECRET() || !secretsMatch(req.params.secret, WH_SECRET())) return;
    const msg = req.body && req.body.message;
    if (!msg || !msg.chat || typeof msg.text !== 'string') return;
    const chatId = String(msg.chat.id);
    const send = (text) => tgSendMessage(TOKEN(), chatId, text);
    const cmd = parseCommand(msg.text);
    const farms = await Farm.find({ archived: { $ne: true } }).sort({ createdAt: 1 }).lean();
    let links = {};
    let link = null;
    let codes = {};
    let codeEntry = null;
    let targetFarmId = '';
    for (const farm of farms) {
      const farmId = String(farm._id);
      const state = await mufRunTelegramFarm(farmId, mufRunWithFarmContext, async () => ({
        links: await readStore(LINKS_KEY, {}),
        codes: cmd.kind === 'link' ? await readStore(CODES_KEY, {}) : {},
      }));
      if (cmd.kind === 'link' && state?.codes?.[cmd.code]) {
        targetFarmId = farmId; codes = state.codes; codeEntry = codes[cmd.code]; break;
      }
      if (state?.links?.[chatId]) {
        targetFarmId = farmId; links = state.links; link = links[chatId]; break;
      }
    }

    if (cmd.kind === 'link') {
      if (!codeEntry || (codeEntry.expires || 0) < Date.now() || !mufTelegramFarmId(codeEntry) || mufTelegramFarmId(codeEntry) !== targetFarmId) return send(TG.linkBad);
      delete codes[cmd.code];
      links[chatId] = {
        userId: codeEntry.userId, username: codeEntry.username,
        laborerId: codeEntry.laborerId, laborerName: codeEntry.laborerName,
        farmId: targetFarmId,
        linkedAt: new Date().toISOString(),
        tgName: [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' '),
      };
      for (const farm of farms) {
        const oldFarmId = String(farm._id);
        if (oldFarmId === targetFarmId) continue;
        await mufRunTelegramFarm(oldFarmId, mufRunWithFarmContext, async () => {
          const oldLinks = await readStore(LINKS_KEY, {});
          if (oldLinks[chatId]) {
            delete oldLinks[chatId];
            await writeStore(LINKS_KEY, oldLinks);
          }
        });
      }
      await mufRunTelegramFarm(targetFarmId, mufRunWithFarmContext, async () => {
        await writeStore(CODES_KEY, codes);
        await writeStore(LINKS_KEY, links);
      });
      return send(TG.linkOk(codeEntry.laborerName || codeEntry.username || 'worker'));
    }

    if (!link) return send(TG.notLinked);
    if (!mufTelegramFarmId(link) || mufTelegramFarmId(link) !== targetFarmId) return send(TG.notLinked);
    return await mufRunTelegramFarm(targetFarmId, mufRunWithFarmContext, async () => {

    const date = todayLocal();
    if (cmd.kind === 'help' || cmd.kind === 'unknown') {
      return send(cmd.kind === 'unknown' ? TG.unknown : HELP_TEXT);
    }

    if (cmd.kind === 'eggs' || cmd.kind === 'milk') { // "doodh" pe bhi anday hi samjho — flock farm hai
      if (!cmd.qty || cmd.qty <= 0) return send(TG.noQty);
      const eggs = await readStore('eggs', []);
      const idx = eggs.findIndex((r) => r.date === date);
      if (idx >= 0) {
        eggs[idx] = { ...eggs[idx], totalEggsCollected: cmd.qty };
      } else {
        eggs.push({ date, totalEggsCollected: cmd.qty, sold: 0, homeUse: 0, brokenWasted: 0 });
      }
      await writeStore('eggs', eggs);
      return send(TG.saved(`آج کے انڈے: ${cmd.qty} — ${date}`));
    }

    if (cmd.kind === 'expense') {
      if (!cmd.qty || cmd.qty <= 0) return send(TG.noQty);
      const hint = expenseHint(cmd.words);
      const category = hint === 'feed' ? 'Feed' : hint === 'medicine' ? 'Medicine' : 'Other';
      const expenses = await readStore('expenses', []);
      expenses.push({
        id: Date.now(),
        date,
        detail: cmd.name || category,
        category,
        amount: cmd.qty,
        notes: `via Telegram (${link.laborerName || link.username || chatId})`,
      });
      await writeStore('expenses', expenses);
      return send(TG.saved(`خرچہ Rs ${cmd.qty.toLocaleString()} (${category}) — ${date}`));
    }

    if (cmd.kind === 'attendance') {
      if (!link.laborerId) return send('آپ کے کھاتے کے ساتھ مزدور پروفائل منسلک نہیں — ایڈمن سے کہیں کہ لنک کوڈ بناتے وقت ورکر بھی چنے۔');
      const attendance = await readStore('laborAttendance', []);
      const already = attendance.find((r) => String(r.workerId) === String(link.laborerId) && r.date === date);
      if (already) return send(`آج کی حاضری پہلے سے لگی ہے (${date})۔`);
      attendance.push({ id: `la-tg-${Date.now()}`, workerId: link.laborerId, date, dayType: 'full', posted: false, notes: 'via Telegram' });
      await writeStore('laborAttendance', attendance);
      return send(TG.saved(`حاضری (پورا دن) — ${date}`));
    }

    if (cmd.kind === 'summary') {
      const [birds, expenses, feed, eggs, settings, vaccinations, customerSales] = await Promise.all([
        readStore('birds', []), readStore('expenses', []), readStore('feed', []),
        readStore('eggs', []), readStore('settings', {}), readStore('vaccinations', []),
        readStore('customerSales', []),
      ]);
      const summary = buildDailySummary({ birds, expenses, feed, eggs, vaccinations, customerSales, settings });
      return send(summary.text);
    }
    });
  } catch (err) {
    console.error('Telegram webhook error:', err.message);
  }
});

const HELP_TEXT = [
  '🐔 عثمان فلاک فارم بوٹ — ایسے لکھیں:',
  '',
  'anday 320  ← آج کے کل انڈے',
  'kharcha 500 chara  ← 500 روپے چارے کا خرچہ',
  'hazri  ← اپنی آج کی حاضری',
  'hisab  ← آج کا خلاصہ',
].join('\n');

// ═══ Evening auto-summary + egg-drop alarm ═════════════════════════
// Settings live in DataStore 'telegram_settings'. The evening push goes
// to every linked chat whose app login is an ADMIN. Triggered by
// cron-job.org pinging GET /api/telegram/cron?key=CRON_SECRET (evening),
// or by the admin's "send now" button in the Telegram panel.
const SETTINGS_KEY = 'telegram_settings';
const SETTINGS_DEFAULTS = { dailySummary: true, dropPct: 20 };

async function readSettings() {
  const v = await readStore(SETTINGS_KEY, {});
  return { ...SETTINGS_DEFAULTS, ...v };
}

function secretsMatch(a, b) {
  const A = Buffer.from(String(a || ''));
  const B = Buffer.from(String(b || ''));
  return A.length === B.length && timingSafeEqual(A, B);
}

// Today's eggs vs previous 7 days' average. Alarm only counts once
// today's egg count is actually entered — an empty day isn't a drop.
async function computeDropStatus() {
  const settings = await readSettings();
  const eggs = await readStore('eggs', []);
  const byDate = new Map(eggs.map((r) => [r.date, r]));
  const today = Number(byDate.get(todayLocal())?.totalEggsCollected || 0);
  const prev = [1, 2, 3, 4, 5, 6, 7].map((i) => Number(byDate.get(daysAgoLocal(i))?.totalEggsCollected || 0));
  const recordedToday = today > 0;
  const check = mufDropCheck(today, prev, settings.dropPct);
  return {
    metric: 'eggs',
    today,
    avg: check.avg,
    pct: check.pct,
    threshold: settings.dropPct,
    ready: check.ready && recordedToday,
    drop: check.ready && recordedToday && check.drop,
  };
}

// Daily summary text = the same full summary the bot's "hisab" reply
// sends, with the egg-drop alarm appended when it fired.
async function buildDailyText() {
  const [birds, expenses, feed, eggs, settings, vaccinations, customerSales] = await Promise.all([
    readStore('birds', []), readStore('expenses', []), readStore('feed', []),
    readStore('eggs', []), readStore('settings', {}), readStore('vaccinations', []),
    readStore('customerSales', []),
  ]);
  const summary = buildDailySummary({ birds, expenses, feed, eggs, vaccinations, customerSales, settings });
  const drop = await computeDropStatus();
  if (drop.drop) {
    return `${summary.text}\n\n${tgDropAlert(drop.pct, `آج: ${drop.today} انڈے`, `7 دن کی اوسط: ${drop.avg} انڈے`)}`;
  }
  return summary.text;
}

// Send today's summary to every linked ADMIN chat. force=true is the
// panel's "send now" button — it skips the once-per-day guard and does
// NOT consume the evening auto-send.
async function pushDailySummary(force = false, allowedFarmIds = null) {
  if (!TOKEN()) return { sent: 0, reason: 'not configured' };
  let farms = await Farm.find({ archived: { $ne: true } }).sort({ createdAt: 1 }).lean();
  if (Array.isArray(allowedFarmIds)) {
    const allowed = new Set(allowedFarmIds.map(String));
    farms = farms.filter((farm) => allowed.has(String(farm._id)));
  }
  const results = [];
  for (const farm of farms) {
    const farmId = String(farm._id);
    const result = await mufRunTelegramFarm(farmId, mufRunWithFarmContext, async () => {
      const tgSettings = await readSettings();
      if (!force && tgSettings.dailySummary === false) return { farmId, sent: 0, reason: 'daily summary turned off' };
      const date = todayLocal();
      if (!force && tgSettings.lastPushDate === date) return { farmId, sent: 0, reason: 'already sent today' };
      const links = await readStore(LINKS_KEY, {});
      const chatIds = [];
      for (const [chatId, link] of Object.entries(links)) {
        if (mufTelegramFarmId(link) !== farmId || !link.userId) continue;
        const u = await User.findById(link.userId);
        if (u && ['owner', 'manager', 'admin'].includes(u.role)) chatIds.push(chatId);
      }
      if (!chatIds.length) return { farmId, sent: 0, reason: 'no linked admin chat' };
      const text = await buildDailyText();
      let sent = 0;
      for (const chatId of chatIds) if (await tgSendMessage(TOKEN(), chatId, text)) sent += 1;
      if (!force) await writeStore(SETTINGS_KEY, { ...tgSettings, lastPushDate: date });
      return { farmId, sent, chats: chatIds.length };
    });
    if (result) results.push(result);
  }
  return { sent: results.reduce((n, r) => n + r.sent, 0), farms: results };
}

// ── Any logged-in user: drop status for the dashboard red card ──
router.get('/alerts', authRequired, async (_req, res) => {
  try { res.json(await computeDropStatus()); }
  catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Admin: auto-summary + alarm settings ──
router.get('/settings', authRequired, requireRole('admin'), async (_req, res) => {
  try { res.json(await readSettings()); }
  catch (e) { res.status(500).json({ error: e.message }); }
});

router.put('/settings', authRequired, requireRole('admin'), async (req, res) => {
  try {
    const next = await readSettings();
    if (typeof (req.body || {}).dailySummary === 'boolean') next.dailySummary = req.body.dailySummary;
    const pct = Number((req.body || {}).dropPct);
    if (Number.isFinite(pct) && pct >= 5 && pct <= 90) next.dropPct = Math.round(pct);
    await writeStore(SETTINGS_KEY, next);
    res.json(next);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Admin: send today's summary right now (test / manual push) ──
router.post('/send-summary', authRequired, requireRole('admin'), async (_req, res) => {
  try {
    const context = mufGetFarmContext();
    if (!context) return res.status(403).json({ error: 'Farm context is required' });
    const allowed = context.mode === 'single' ? [context.farmId] : (context.farmIds || []);
    res.json(await pushDailySummary(true, allowed));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── cron-job.org: GET /api/telegram/cron?key=CRON_SECRET (evening ping) ──
router.get('/cron', async (req, res) => {
  try {
    if (!MUF_ENV.cronSecret) return res.status(503).json({ error: 'CRON_SECRET not configured' });
    if (!secretsMatch(req.headers['x-cron-key'] || req.query.key, MUF_ENV.cronSecret)) return res.status(401).json({ error: 'Unauthorized' });
    res.json(await pushDailySummary(false));
  } catch (e) { res.status(500).json({ error: e.message }); }
});


// Boot-time webhook registration (non-fatal).
export async function initTelegram() {
  try {
    if (!TOKEN() || !WH_SECRET()) return;
    const base = (MUF_ENV.appUrl || '').replace(/\/+$/, '');
    if (!base) { console.log('📨 Telegram: set APP_URL to auto-register the webhook.'); return; }
    const ok = await tgSetWebhook(TOKEN(), `${base}/api/telegram/webhook/${WH_SECRET()}`);
    console.log(ok ? '📨 Telegram webhook registered.' : '📨 Telegram webhook registration failed (will still accept pushes).');
  } catch (e) { console.error('Telegram init failed (non-fatal):', e.message); }
}

export default router;

import 'dotenv/config';
import mongoose from 'mongoose';
import { connectDB, Farm, User, MUF_FARM_MODELS, MUF_FARM_SCOPED_NAMES } from '../db.js';
import { mufMigrateFarms, mufRunUnscoped } from '../muf-farms.mjs';
import { MUF_ENV } from '../muf-env.mjs';

const dryRun = process.argv.includes('--dry-run');
if (MUF_ENV.memoryMode && !MUF_ENV.mongoUri) {
  console.error('This script requires a real MongoDB URI. Memory/demo data migrates automatically and is not persistent.');
  process.exit(2);
}
await connectDB();

const report = await mufRunUnscoped(async () => {
  const farms = await Farm.countDocuments({});
  const users = await User.find({}).lean();
  const missing = {};
  for (const name of MUF_FARM_SCOPED_NAMES) {
    missing[name] = await MUF_FARM_MODELS[name].countDocuments({ $or: [{ farmId: { $exists: false } }, { farmId: null }] });
  }
  return {
    farms,
    users: users.length,
    legacyAdmins: users.filter((u) => u.role === 'admin').length,
    usersWithoutFarmAssignment: users.filter((u) => ['manager', 'worker'].includes(u.role) && !(u.farmIds || []).length).length,
    recordsMissingFarmId: missing,
  };
});
console.log(JSON.stringify({ mode: dryRun ? 'dry-run (no changes)' : 'apply', before: report }, null, 2));

if (!dryRun) {
  const result = await mufMigrateFarms({
    Farm, User, models: MUF_FARM_MODELS, names: MUF_FARM_SCOPED_NAMES,
    log: (message) => console.log('[farms] ' + message),
  });
  // The old globally-unique key index prevents the same bucket key in a second
  // farm. Replace it only after the records have been safely tagged.
  const collection = mongoose.connection.collection('datastores');
  try { await collection.dropIndex('key_1'); } catch (err) {
    if (err.codeName !== 'IndexNotFound' && err.code !== 27) throw err;
  }
  await collection.createIndex({ farmId: 1, key: 1 }, { unique: true, name: 'datastore_farm_key_unique' });
  for (const name of MUF_FARM_SCOPED_NAMES) {
    if (name !== 'DataStore') await MUF_FARM_MODELS[name].collection.createIndex({ farmId: 1 });
  }
  console.log(JSON.stringify({ applied: result }, null, 2));
}
await mongoose.disconnect();
